import{t as e}from"./expand-B9sP1tsw.js";var t=[[[3,1,`number`,`In the number 352, what does the digit 5 stand for?`,`5 tens (50)`,[`5 ones`,`5 hundreds`,`5 thousands`],`In 352 the 3 is in the hundreds place, the 5 in the tens place and the 2 in the ones place.`],[3,1,`number`,`Which of these numbers is even?`,`14`,[`7`,`9`,`21`],`Even numbers can be shared into two equal groups; they end in 0, 2, 4, 6 or 8.`],[3,2,`number`,`What is the smallest number you can make with the digits 4, 1 and 7, using each once?`,`147`,[`417`,`714`,`174`],`Put the smallest digit in the hundreds place, then the next smallest: 147.`],[3,2,`number`,`Which number comes just before 600?`,`599`,[`601`,`590`,`500`],`Counting back one from 600 gives 599.`],[3,2,`number`,`How many tens make one hundred?`,`10`,[`100`,`1`,`20`],`Ten tens make one hundred.`],[3,3,`number`,`Rounded to the nearest ten, what is 46?`,`50`,[`40`,`45`,`60`],`46 is nearer to 50 than to 40, so it rounds up.`],[3,3,`number`,`Zero is an even number.`,`True`,[`False`],`Zero divided by 2 gives 0 with nothing left over, so zero is even.`],[4,1,`number`,`Which of these is a multiple of 6?`,`42`,[`32`,`26`,`15`],`6 × 7 = 42. The others do not divide exactly by 6.`],[4,1,`number`,`Every multiple of 10 ends in a zero.`,`True`,[`False`],`10, 20, 30… 1,250: multiplying by 10 always puts a 0 in the ones place.`],[4,2,`number`,`What is the value of the digit 8 in 4,825?`,`800`,[`8`,`80`,`8,000`],`4,825 is 4 thousands, 8 hundreds, 2 tens and 5 ones.`],[4,2,`number`,`Which Roman numeral stands for 50?`,`L`,[`X`,`C`,`V`],`I = 1, V = 5, X = 10, L = 50 and C = 100.`],[4,3,`number`,`What is 3,000 + 400 + 7 written as one number?`,`3,407`,[`3,470`,`347`,`34,007`],`3 thousands, 4 hundreds, 0 tens and 7 ones make 3,407.`],[4,3,`number`,`A factor of a number divides into it exactly. Which of these is a factor of 18?`,`6`,[`4`,`5`,`8`],`18 ÷ 6 = 3 exactly; 18 ÷ 4, 18 ÷ 5 and 18 ÷ 8 leave remainders.`],[5,1,`number`,`What is a prime number?`,`A whole number greater than 1 with exactly two factors`,[`Any whole number that ends with the digit 1`,`Any even number bigger than ten`,`A number that has no factors at all`],`Primes such as 2, 3, 5, 7 and 11 can only be divided exactly by 1 and themselves.`],[5,1,`number`,`Which is greater, −3 or −8?`,`−3`,[`−8`,`They are equal`,`It cannot be told`],`On a number line −3 is to the right of −8, so it is greater.`],[5,2,`number`,`Which of these numbers is prime?`,`29`,[`27`,`21`,`33`],`27 = 3 × 9, 21 = 3 × 7 and 33 = 3 × 11, but 29's only factors are 1 and 29.`],[5,2,`number`,`What is 10 squared (10²)?`,`100`,[`20`,`1,000`,`12`],`Squaring means multiplying a number by itself: 10 × 10 = 100.`],[5,2,`number`,`1 is a prime number.`,`False`,[`True`],`A prime has exactly two factors; 1 has only one, so it is not prime.`],[5,3,`number`,`Round 3,749 to the nearest hundred.`,`3,700`,[`3,800`,`3,750`,`4,000`],`The tens digit is 4, which is less than 5, so round down to 3,700.`],[5,3,`number`,`What is a negative number?`,`A number less than zero`,[`A number with no value`,`A number that is very large`,`A number that is a fraction`],`On a thermometer, −5 °C is five degrees below zero.`],[6,1,`number`,`What is the highest common factor (HCF) of 12 and 18?`,`6`,[`3`,`2`,`36`],`The factors that 12 and 18 share are 1, 2, 3 and 6; the highest is 6.`],[6,1,`number`,`Which is the prime factorisation of 12?`,`2 × 2 × 3`,[`3 × 4`,`2 × 6`,`1 × 12`],`Breaking 12 down into primes only: 12 = 2 × 2 × 3.`],[6,2,`number`,`What is the lowest common multiple (LCM) of 4 and 6?`,`12`,[`24`,`2`,`10`],`Multiples of 4: 4, 8, 12…; of 6: 6, 12…; the first one they share is 12.`],[6,2,`number`,`What is 2 cubed (2³)?`,`8`,[`6`,`9`,`4`],`Cubing means using the number as a factor three times: 2 × 2 × 2 = 8.`],[6,2,`number`,`The product of two negative numbers is positive.`,`True`,[`False`],`For example, −3 × −4 = 12.`],[6,3,`number`,`What is the square root of 81?`,`9`,[`8`,`40.5`,`18`],`9 × 9 = 81, so √81 = 9.`],[6,3,`number`,`Start at −4 on a number line and add 10. Where do you end up?`,`6`,[`−14`,`14`,`−6`],`Moving 10 to the right from −4 passes 0 after 4 steps and stops at 6.`],[7,1,`number`,`Multiply −6 by 3.`,`−18`,[`18`,`−9`,`−3`],`A negative times a positive is negative: −6 × 3 = −18.`],[7,1,`number`,`What is the absolute value of −12?`,`12`,[`−12`,`0`,`1/12`],`Absolute value is the distance from zero, which is never negative.`],[7,2,`number`,`Which of these numbers is irrational?`,`√2`,[`½`,`0.25`,`−3`],`√2 = 1.41421… goes on for ever without repeating, so it cannot be written as a fraction.`],[7,2,`number`,`Every square number has an odd number of factors.`,`True`,[`False`],`Factors come in pairs, except the square root, which pairs with itself: 16 has 1, 2, 4, 8 and 16.`],[7,3,`number`,`What is 5⁰ (5 to the power 0)?`,`1`,[`0`,`5`,`50`],`Any non-zero number to the power 0 equals 1.`],[7,3,`number`,`How is 4,500,000 written in standard form?`,`4.5 × 10⁶`,[`45 × 10⁵`,`4.5 × 10⁵`,`0.45 × 10⁷`],`Standard form has one non-zero digit before the point: 4.5 × 1,000,000.`],[8,1,`number`,`What is 10⁻² as a decimal?`,`0.01`,[`0.1`,`−100`,`−20`],`10⁻² = 1 ÷ 10² = 1 ÷ 100 = 0.01.`],[8,1,`number`,`The number π is exactly 22/7.`,`False`,[`True`],`22/7 is only a close approximation; π = 3.14159… never ends or repeats.`],[8,2,`number`,`What is the cube root of 64?`,`4`,[`8`,`16`,`21⅓`],`4 × 4 × 4 = 64.`],[8,2,`number`,`Simplify 2³ × 2⁴.`,`2⁷`,[`2¹²`,`4⁷`,`2¹`],`When multiplying powers of the same base, add the indices: 3 + 4 = 7.`],[8,3,`number`,`Which of these is a rational number?`,`0.333… (recurring)`,[`π`,`√3`,`√5`],`0.333… equals ⅓, a fraction; π, √3 and √5 cannot be written as fractions.`],[8,3,`number`,`What is 3.2 × 10⁻³ as an ordinary number?`,`0.0032`,[`3,200`,`0.032`,`0.00032`],`A power of −3 means moving the decimal point 3 places to the left.`],[3,1,`fractions`,`A pizza is cut into 4 equal slices and you eat 1. What fraction did you eat?`,`One quarter (¼)`,[`One half (½)`,`One third (⅓)`,`Four (4)`],`One out of four equal parts is one quarter.`],[3,2,`fractions`,`Which fraction is the same as one half?`,`2/4`,[`1/4`,`3/4`,`2/3`],`Two quarters make the same amount as one half.`],[3,2,`fractions`,`In the fraction ¾, the bottom number shows how many equal parts the whole is split into.`,`True`,[`False`],`The bottom number (denominator) is 4: the whole is split into 4 equal parts, and 3 are taken.`],[3,3,`fractions`,`Which is bigger, 1/2 or 1/4?`,`1/2`,[`1/4`,`They are equal`,`You cannot tell`],`Sharing between 2 gives bigger pieces than sharing between 4.`],[4,1,`fractions`,`What is the top number of a fraction called?`,`The numerator`,[`The denominator`,`The quotient`,`The product`],`In ¾ the numerator is 3, the parts taken; the denominator 4 is the number of equal parts.`],[4,2,`fractions`,`Half of a class of 20 children went on a trip. How many went?`,`10`,[`40`,`5`,`2`],`Half of 20 means 20 ÷ 2 = 10.`],[4,2,`fractions`,`Which decimal is the same as ½?`,`0.5`,[`0.2`,`0.05`,`1.2`],`½ = 5 tenths = 0.5.`],[4,3,`fractions`,`Add 1/5 and 2/5.`,`3/5`,[`3/10`,`2/25`,`1/5`],`When the denominators are the same, add the numerators: 1 + 2 = 3 fifths.`],[4,3,`fractions`,`How many tenths make one whole?`,`10`,[`1`,`100`,`5`],`Ten tenths make one whole: 10 × 0.1 = 1.`],[5,1,`fractions`,`What is 0.25 as a fraction?`,`¼`,[`½`,`⅕`,`2/5`],`0.25 = 25 hundredths = 1 quarter.`],[5,1,`fractions`,`'Per cent' means 'out of 100'.`,`True`,[`False`],`35 % means 35 out of every 100.`],[5,2,`fractions`,`What is 50% of 80?`,`40`,[`50`,`30`,`160`],`50 % means half, and half of 80 is 40.`],[5,2,`fractions`,`Which is the largest: 0.6, 0.06 or 0.56?`,`0.6`,[`0.06`,`0.56`,`They are all equal`],`0.6 = 0.60, which is more than 0.56 and much more than 0.06.`],[5,3,`fractions`,`What is 3/4 written as a percentage?`,`75 %`,[`34 %`,`43 %`,`25 %`],`3/4 = 75/100 = 75 %.`],[5,3,`fractions`,`Simplify 6/8.`,`3/4`,[`2/3`,`It cannot be simplified`,`1/2`],`Divide the top and bottom by 2: 6/8 = 3/4.`],[6,1,`fractions`,`What is an improper fraction?`,`One whose numerator is bigger than its denominator`,[`One that cannot be simplified at all`,`One with a denominator of exactly 10`,`One that is less than zero`],`7/4 is improper; as a mixed number it is 1¾.`],[6,1,`fractions`,`What is 0.07 as a percentage?`,`7 %`,[`70 %`,`0.07 %`,`0.7 %`],`Multiply by 100: 0.07 × 100 = 7 %.`],[6,2,`fractions`,`Write 9/4 as a mixed number.`,`2¼`,[`4½`,`1¾`,`2¾`],`9 ÷ 4 = 2 remainder 1, so 9/4 = 2¼.`],[6,2,`fractions`,`What is two-thirds of three-quarters?`,`1/2`,[`5/7`,`6/7`,`8/9`],`'Of' means multiply: (2 × 3)/(3 × 4) = 6/12 = 1/2.`],[6,2,`fractions`,`For positive numbers, multiplying by a fraction smaller than 1 always gives a smaller answer.`,`True`,[`False`],`Taking ½ of something, for example, halves it.`],[6,3,`fractions`,`How many quarters fit into one half (½ ÷ ¼)?`,`2`,[`1/8`,`1/2`,`4`],`Dividing by ¼ is the same as multiplying by 4: ½ × 4 = 2.`],[6,3,`fractions`,`A shirt costing 400 taka is reduced by 25 %. What is the new price?`,`300 taka`,[`375 taka`,`100 taka`,`325 taka`],`25 % of 400 is 100, and 400 − 100 = 300.`],[7,1,`fractions`,`What is ⅓ as a recurring decimal?`,`0.333…`,[`0.3`,`0.13`,`3.3`],`1 ÷ 3 = 0.3333…, with the 3 repeating for ever.`],[7,1,`fractions`,`A ratio of 4 : 6 can be simplified to 2 : 3.`,`True`,[`False`],`Divide both parts by 2.`],[7,2,`fractions`,`Increase 60 by 10 %.`,`66`,[`70`,`61`,`6`],`10 % of 60 is 6, and 60 + 6 = 66.`],[7,2,`fractions`,`A test score of 18 out of 24 is what percentage?`,`75 %`,[`18 %`,`80 %`,`72 %`],`18 ÷ 24 = 0.75 = 75 %.`],[7,3,`fractions`,`Boys and girls in a class are in the ratio 2 : 3. There are 30 children. How many are girls?`,`18`,[`12`,`20`,`15`],`Split 30 into 5 equal shares of 6: the girls have 3 shares, 18.`],[7,3,`fractions`,`Is 5/8 more than, less than or equal to 0.6?`,`More than 0.6`,[`Less than 0.6`,`Equal to 0.6`,`It cannot be told`],`5/8 = 0.625, which is greater than 0.6.`],[8,1,`fractions`,`A price rises from 200 to 250 taka. What is the percentage increase?`,`25 %`,[`50 %`,`20 %`,`250 %`],`The increase is 50, and 50 ÷ 200 = 0.25 = 25 %.`],[8,1,`fractions`,`A 50 % increase followed by a 50 % decrease brings you back to where you started.`,`False`,[`True`],`100 + 50 % = 150, then 150 − 50 % = 75: you end lower.`],[8,2,`fractions`,`What is 0.222… (0.2 recurring) as a fraction?`,`2/9`,[`1/5`,`2/10`,`22/100`],`Let x = 0.222…; then 10x − x = 2, so 9x = 2 and x = 2/9.`],[8,2,`fractions`,`After a 20 % discount, a bag costs 400 taka. What was the original price?`,`500 taka`,[`480 taka`,`420 taka`,`320 taka`],`400 taka is 80 % of the original price, and 400 ÷ 0.8 = 500.`],[8,3,`fractions`,`Money in a bank grows by 10 % each year. How much does 1,000 taka become after two years?`,`1,210 taka`,[`1,200 taka`,`1,020 taka`,`1,100 taka`],`Compound growth: 1,000 × 1.1 × 1.1 = 1,210.`],[8,3,`fractions`,`Which is the better buy: 3 pens for 45 taka or 5 pens for 70 taka?`,`5 pens for 70 taka`,[`3 pens for 45 taka`,`They cost the same per pen`,`It cannot be worked out`],`45 ÷ 3 = 15 taka a pen; 70 ÷ 5 = 14 taka a pen, so 5 for 70 is cheaper per pen.`]],[[3,1,`geometry`,`A flat shape with four equal sides and four right angles is a…`,`square`,[`rectangle`,`triangle`,`pentagon`],`A square is a special rectangle whose sides are all the same length.`],[3,1,`geometry`,`Which 3D shape is shaped like a ball?`,`A sphere`,[`A cube`,`A cone`,`A cylinder`],`Every point on a sphere's surface is the same distance from its centre.`],[3,2,`geometry`,`How many corners (vertices) does a rectangle have?`,`4`,[`3`,`5`,`6`],`A rectangle has four sides and four corners, all right angles.`],[3,2,`geometry`,`Which flat shape has no straight sides?`,`A circle`,[`A square`,`A triangle`,`A rectangle`],`A circle has one curved edge and no corners.`],[3,3,`geometry`,`A shape with five straight sides is called a…`,`pentagon`,[`hexagon`,`octagon`,`quadrilateral`],`A pentagon has five sides (penta- means five). A hexagon has six sides and an octagon eight.`],[3,3,`geometry`,`A cube has six faces.`,`True`,[`False`],`A cube has 6 square faces, 12 edges and 8 vertices, like a dice.`],[4,1,`geometry`,`What do we call an angle that is exactly a quarter turn?`,`A right angle`,[`An acute angle`,`An obtuse angle`,`A straight angle`],`A quarter turn is 90°, a right angle, like the corner of a page.`],[4,1,`geometry`,`A triangle can have two right angles.`,`False`,[`True`],`A triangle's angles add up to 180°, so two right angles would leave nothing for the third angle.`],[4,2,`geometry`,`An angle smaller than a right angle is called…`,`acute`,[`obtuse`,`reflex`,`straight`],`Acute angles are less than 90°; obtuse angles are between 90° and 180°.`],[4,2,`geometry`,`How many lines of symmetry does a square have?`,`4`,[`2`,`1`,`8`],`Two lines through the middles of opposite sides and two along the diagonals.`],[4,3,`geometry`,`Which 3D shape has two circular faces and one curved surface?`,`A cylinder`,[`A cone`,`A sphere`,`A square-based prism`],`A tin can is a cylinder.`],[4,3,`geometry`,`What are parallel lines?`,`Lines that stay the same distance apart and never meet`,[`Lines that cross at a right angle`,`Lines that meet at one point`,`Lines that bend into a circle`],`Railway tracks are a good picture of parallel lines.`],[5,1,`geometry`,`How many degrees are there in a full turn?`,`360°`,[`180°`,`90°`,`100°`],`A full turn is 360°; a half turn is 180° and a quarter turn 90°.`],[5,1,`geometry`,`Angles on a straight line add up to 180°.`,`True`,[`False`],`A straight line is a half turn, which is 180°.`],[5,2,`geometry`,`What do the angles inside any triangle add up to?`,`180°`,[`360°`,`90°`,`270°`],`Tear off a triangle's three corners and they fit together along a straight line.`],[5,2,`geometry`,`Which triangle has all three sides equal?`,`An equilateral triangle`,[`An isosceles triangle`,`A scalene triangle`,`A right-angled triangle`],`An equilateral triangle also has three equal angles of 60°.`],[5,3,`geometry`,`An angle of 120° is…`,`obtuse`,[`acute`,`reflex`,`a right angle`],`It is more than 90° but less than 180°.`],[5,3,`geometry`,`Which four-sided shape has exactly one pair of parallel sides?`,`A trapezium`,[`A rectangle`,`A rhombus`,`A square`],`A trapezium (called a trapezoid in the USA) has one pair of parallel sides.`],[6,1,`geometry`,`What is the distance from the centre of a circle to its edge called?`,`The radius`,[`The diameter`,`The circumference`,`The chord`],`The diameter goes right across through the centre, so it is twice the radius.`],[6,2,`geometry`,`A circle's diameter is 10 cm. What is its radius?`,`5 cm`,[`20 cm`,`10 cm`,`31.4 cm`],`The radius is half the diameter: 10 ÷ 2 = 5 cm.`],[6,2,`geometry`,`What do the angles inside a quadrilateral add up to?`,`360°`,[`180°`,`90°`,`540°`],`A diagonal splits any quadrilateral into two triangles: 2 × 180° = 360°.`],[6,2,`geometry`,`Vertically opposite angles are equal.`,`True`,[`False`],`When two straight lines cross, the angles opposite each other at the crossing are equal.`],[6,3,`geometry`,`How many faces does a triangular prism have?`,`5`,[`6`,`3`,`9`],`Two triangular ends and three rectangular sides make 5 faces.`],[6,3,`geometry`,`Which transformation flips a shape over a line?`,`A reflection`,[`A rotation`,`A translation`,`An enlargement`],`A reflection gives a mirror image; a rotation turns and a translation slides.`],[7,1,`geometry`,`A rhombus has four equal sides.`,`True`,[`False`],`A rhombus looks like a pushed-over square: equal sides, but its angles need not be right angles.`],[7,1,`geometry`,`What is the sum of the interior angles of a pentagon?`,`540°`,[`360°`,`180°`,`720°`],`(5 − 2) × 180° = 540°: a pentagon splits into three triangles.`],[7,2,`geometry`,`What does Pythagoras' theorem say about a right-angled triangle?`,`a² + b² = c², where c is the longest side`,[`a + b = c for its three sides`,`Its angles add up to 360°`,`All three of its sides are equal`],`The square on the hypotenuse equals the sum of the squares on the other two sides.`],[7,2,`geometry`,`A right-angled triangle has shorter sides of 3 cm and 4 cm. How long is the longest side?`,`5 cm`,[`7 cm`,`6 cm`,`12 cm`],`3² + 4² = 9 + 16 = 25, and √25 = 5.`],[7,3,`geometry`,`Each interior angle of a regular hexagon measures…`,`120°`,[`60°`,`108°`,`135°`],`A hexagon's angles add up to 720°; shared equally between 6 angles, each is 120°.`],[7,3,`geometry`,`What is a polygon?`,`A flat shape with straight sides`,[`A 3D shape with curved faces`,`A circle with a hole in it`,`A line that goes on for ever`],`Triangles, squares and hexagons are polygons; circles are not.`],[8,1,`geometry`,`What is each exterior angle of a regular octagon?`,`45°`,[`135°`,`60°`,`90°`],`The exterior angles of any polygon add up to 360°, and 360° ÷ 8 = 45°.`],[8,1,`geometry`,`Similar shapes always have equal side lengths.`,`False`,[`True`],`Similar shapes have the same angles and proportional sides; only congruent shapes have equal sides.`],[8,2,`geometry`,`Two shapes are congruent when they are…`,`exactly the same shape and size`,[`the same shape but different sizes`,`the same colour`,`both symmetrical`],`Congruent shapes fit exactly on top of each other, perhaps after a flip or turn.`],[8,2,`geometry`,`A shape is enlarged by a scale factor of 3. How many times bigger is its area?`,`9`,[`3`,`6`,`27`],`Lengths are multiplied by 3, so areas are multiplied by 3² = 9.`],[8,3,`geometry`,`What is the angle at the edge of a circle in a semicircle (standing on a diameter)?`,`90°`,[`180°`,`45°`,`60°`],`Any triangle drawn on a diameter with its third corner on the circle has a right angle there.`],[8,3,`geometry`,`When a line crosses two parallel lines, which pair of angles on the same side adds up to 180°?`,`Co-interior angles`,[`Alternate angles`,`Corresponding angles`,`Vertically opposite angles`],`Alternate and corresponding angles are equal; co-interior angles add up to 180°.`],[3,1,`measurement`,`How many centimetres are there in one metre?`,`100`,[`10`,`1,000`,`60`],`Centi- means a hundredth, so 100 centimetres make a metre.`],[3,1,`measurement`,`How many minutes are in one hour?`,`60`,[`100`,`30`,`24`],`An hour has 60 minutes, and a minute has 60 seconds.`],[3,2,`measurement`,`When a clock shows exactly three o'clock, where does the minute hand point?`,`To the 12`,[`To the 3`,`To the 6`,`To the 9`],`At every o'clock the minute hand points straight up to the 12.`],[3,2,`measurement`,`Which unit would you use for the weight of an apple?`,`Grams`,[`Kilometres`,`Litres`,`Hours`],`An apple weighs about 150 to 200 grams.`],[3,3,`measurement`,`You pay with a 50-taka note for something that costs 35 taka. How much change do you get?`,`15 taka`,[`25 taka`,`85 taka`,`5 taka`],`Change is what is left over: 50 − 35 = 15 taka.`],[3,3,`measurement`,`A litre measures how much liquid a container holds.`,`True`,[`False`],`Litres and millilitres measure capacity, such as a bottle of water.`],[4,1,`measurement`,`How many grams make one kilogram?`,`1,000`,[`100`,`10`,`10,000`],`Kilo- means a thousand.`],[4,1,`measurement`,`Half an hour is 30 minutes.`,`True`,[`False`],`Half of 60 minutes is 30.`],[4,2,`measurement`,`What is quarter to three in the afternoon in 24-hour time?`,`14:45`,[`2:45`,`02:45`,`24:45`],`Quarter to three is 2:45; after midday add 12 to the hours: 14:45.`],[4,2,`measurement`,`What is the perimeter of a rectangle 5 cm long and 3 cm wide?`,`16 cm`,[`15 cm`,`8 cm`,`30 cm`],`The perimeter is the distance all the way round: 5 + 3 + 5 + 3 = 16.`],[4,3,`measurement`,`How many days are there in a leap year?`,`366`,[`365`,`364`,`360`],`A leap year has an extra day, 29 February.`],[4,3,`measurement`,`How many millilitres are in a litre?`,`1,000`,[`100`,`10`,`500`],`Milli- means a thousandth.`],[5,1,`measurement`,`What is the area of a rectangle 6 m long and 4 m wide?`,`24 m²`,[`20 m²`,`10 m²`,`24 m`],`Area = length × width = 6 × 4 = 24 square metres.`],[5,1,`measurement`,`One kilometre is 1,000 metres.`,`True`,[`False`],`Kilo- means a thousand, so a kilometre is a thousand metres.`],[5,2,`measurement`,`A film starts at 4:15 pm and lasts 1 hour 50 minutes. When does it end?`,`6:05 pm`,[`5:65 pm`,`5:05 pm`,`6:15 pm`],`4:15 + 1 hour = 5:15; + 50 minutes = 6:05.`],[5,2,`measurement`,`Which is longer: 1.5 km or 1,400 m?`,`1.5 km`,[`1,400 m`,`They are the same`,`It depends on the road`],`1.5 km = 1,500 m, which is 100 m more than 1,400 m.`],[5,3,`measurement`,`How many seconds are in 3 minutes?`,`180`,[`300`,`60`,`30`],`3 × 60 = 180 seconds.`],[5,3,`measurement`,`What is the volume of a cube with sides of 3 cm?`,`27 cm³`,[`9 cm³`,`18 cm³`,`27 cm²`],`Volume = 3 × 3 × 3 = 27 cubic centimetres.`],[6,1,`measurement`,`What is the area of a triangle with base 10 cm and height 6 cm?`,`30 cm²`,[`60 cm²`,`16 cm²`,`36 cm²`],`Area of a triangle = ½ × base × height = ½ × 10 × 6 = 30.`],[6,1,`measurement`,`A millimetre is smaller than a centimetre.`,`True`,[`False`],`Ten millimetres make one centimetre.`],[6,2,`measurement`,`About how many centimetres are in one inch?`,`2.5`,[`10`,`1`,`25`],`One inch is exactly 2.54 cm.`],[6,2,`measurement`,`A car travels 120 km in 2 hours. What is its average speed?`,`60 km/h`,[`240 km/h`,`120 km/h`,`30 km/h`],`Speed = distance ÷ time = 120 ÷ 2 = 60 km per hour.`],[6,3,`measurement`,`How many square centimetres are in one square metre?`,`10,000`,[`100`,`1,000`,`1,000,000`],`A square metre is 100 cm by 100 cm, which is 10,000 cm².`],[6,3,`measurement`,`Which unit would you use for how much a bucket holds?`,`Litres`,[`Metres`,`Kilograms`,`Degrees`],`Capacity is measured in litres and millilitres.`],[7,1,`measurement`,`A hectare is 10,000 square metres.`,`True`,[`False`],`A hectare is a square 100 m by 100 m, used to measure farmland.`],[7,1,`measurement`,`What is the circumference of a circle with diameter 10 cm? (Use π ≈ 3.14.)`,`31.4 cm`,[`15.7 cm`,`314 cm`,`62.8 cm`],`Circumference = π × diameter = 3.14 × 10 = 31.4 cm.`],[7,2,`measurement`,`What is the area of a circle with radius 10 cm? (Use π ≈ 3.14.)`,`314 cm²`,[`31.4 cm²`,`62.8 cm²`,`100 cm²`],`Area = π × r² = 3.14 × 100 = 314 cm².`],[7,2,`measurement`,`A map's scale is 1 : 50,000. What real distance does 2 cm on the map stand for?`,`1 km`,[`100 m`,`50 km`,`25 km`],`2 × 50,000 cm = 100,000 cm = 1,000 m = 1 km.`],[7,3,`measurement`,`On which temperature scale does water freeze at 32 degrees?`,`Fahrenheit`,[`Celsius`,`Kelvin`,`Richter`],`Water freezes at 32 °F, 0 °C and 273.15 K.`],[7,3,`measurement`,`What is the volume of a cuboid measuring 5 cm by 4 cm by 2 cm?`,`40 cm³`,[`11 cm³`,`20 cm³`,`80 cm³`],`Volume = length × width × height = 5 × 4 × 2 = 40.`],[8,1,`measurement`,`An object has a mass of 200 g and a volume of 50 cm³. What is its density?`,`4 g/cm³`,[`10,000 g/cm³`,`250 g/cm³`,`0.25 g/cm³`],`Density = mass ÷ volume = 200 ÷ 50 = 4 g/cm³.`],[8,1,`measurement`,`1 cm³ of water holds 1 millilitre.`,`True`,[`False`],`A millilitre is defined as one cubic centimetre.`],[8,2,`measurement`,`How long does a journey of 150 km take at 60 km/h?`,`2½ hours`,[`2 hours`,`90 minutes`,`3 hours`],`Time = distance ÷ speed = 150 ÷ 60 = 2.5 hours.`],[8,2,`measurement`,`What is the surface area of a cube with edges of 2 cm?`,`24 cm²`,[`8 cm²`,`12 cm²`,`16 cm²`],`Each of the 6 faces is 2 × 2 = 4 cm², so 6 × 4 = 24 cm².`],[8,3,`measurement`,`What is the volume of a cylinder with radius 2 cm and height 5 cm? (Use π ≈ 3.14.)`,`62.8 cm³`,[`31.4 cm³`,`20 cm³`,`125.6 cm³`],`Volume = π × r² × h = 3.14 × 4 × 5 = 62.8 cm³.`],[8,3,`measurement`,`A length is 4.6 m, correct to 1 decimal place. What is its lower bound?`,`4.55 m`,[`4.5 m`,`4.59 m`,`4.65 m`],`Anything from 4.55 up to (but not including) 4.65 rounds to 4.6.`]],[[3,1,`algebra`,`What comes next in the pattern 2, 4, 6, 8, …?`,`10`,[`9`,`12`,`16`],`The pattern adds 2 each time: 8 + 2 = 10.`],[3,2,`algebra`,`Which number is missing? 7 + ? = 12`,`5`,[`4`,`19`,`6`],`12 − 7 = 5, so 7 + 5 = 12.`],[3,2,`algebra`,`Addition and subtraction are inverse operations.`,`True`,[`False`],`One undoes the other: 5 + 3 = 8, so 8 − 3 = 5.`],[3,3,`algebra`,`Which multiplication matches 4 + 4 + 4?`,`3 × 4`,[`4 × 4`,`3 + 4`,`12 × 3`],`Three lots of four: 3 × 4 = 12.`],[4,1,`algebra`,`What is the rule for the sequence 3, 6, 9, 12, …?`,`Add 3 each time`,[`Add 2 each time`,`Double each time`,`Take away 3 each time`],`Each number is 3 more than the one before: these are the multiples of 3.`],[4,2,`algebra`,`If □ × 6 = 42, what number goes in the box?`,`7`,[`6`,`36`,`8`],`Division undoes multiplication: 42 ÷ 6 = 7, and 7 × 6 = 42.`],[4,2,`algebra`,`Multiplication can be done in either order: 3 × 5 = 5 × 3.`,`True`,[`False`],`Three rows of five and five rows of three both make 15.`],[4,3,`algebra`,`Ali is 4 years older than Mina. Mina is 9. How old is Ali?`,`13`,[`5`,`36`,`9`],`Older means more years: 9 + 4 = 13.`],[5,1,`algebra`,`In algebra, what does 3n mean?`,`3 × n`,[`3 + n`,`n − 3`,`3 ÷ n`],`A number written next to a letter means multiply: 3n is 3 lots of n.`],[5,2,`algebra`,`If n = 5, what is 2n + 1?`,`11`,[`7`,`25`,`21`],`2 × 5 = 10, then add 1: 11.`],[5,2,`algebra`,`In algebra, a letter can stand for a number we do not know yet.`,`True`,[`False`],`Letters such as x or n stand for unknown or changing numbers.`],[5,3,`algebra`,`Which number makes x + 8 = 15 true?`,`7`,[`23`,`8`,`15`],`Take 8 away from both sides: x = 15 − 8 = 7.`],[5,3,`algebra`,`What is the next square number after 16?`,`25`,[`20`,`18`,`32`],`16 = 4 × 4, so the next square number is 5 × 5 = 25.`],[6,1,`algebra`,`Simplify a + a + a.`,`3a`,[`a³`,`3 + a`,`a + 3`],`Three lots of a make 3a. a³ would mean a × a × a.`],[6,1,`algebra`,`In the expression 2x + 7, the number 7 is called a constant.`,`True`,[`False`],`A constant does not change when x changes.`],[6,2,`algebra`,`Solve 4x = 28.`,`x = 7`,[`x = 24`,`x = 32`,`x = 112`],`Divide both sides by 4: x = 28 ÷ 4 = 7.`],[6,2,`algebra`,`What is the nth term of the sequence 5, 10, 15, 20, …?`,`5n`,[`n + 5`,`5 + n²`,`10n`],`Each term is 5 times its position: the 1st is 5, the 2nd is 10, and so on.`],[6,3,`algebra`,`Expand 3(x + 2).`,`3x + 6`,[`3x + 2`,`x + 6`,`3x + 5`],`Multiply both terms in the bracket by 3: 3 × x + 3 × 2.`],[6,3,`algebra`,`A taxi charges 50 taka plus 20 taka per kilometre. Which formula gives the cost C for k kilometres?`,`C = 50 + 20k`,[`C = 20 + 50k`,`C = 70k`,`C = 50k − 20`],`The fixed 50 taka is paid once; 20 taka is paid for each of the k kilometres.`],[7,1,`algebra`,`Solve 2x + 3 = 11.`,`x = 4`,[`x = 7`,`x = 5.5`,`x = 8`],`Take 3 from both sides: 2x = 8. Then divide by 2: x = 4.`],[7,1,`algebra`,`x² means x multiplied by itself.`,`True`,[`False`],`x² = x × x; it does not mean 2 × x.`],[7,2,`algebra`,`Factorise 6x + 9.`,`3(2x + 3)`,[`6(x + 9)`,`2(3x + 9)`,`9(6x + 1)`],`3 is the highest common factor of 6x and 9.`],[7,2,`algebra`,`What is the gradient of the line y = 3x + 2?`,`3`,[`2`,`5`,`1/3`],`In y = mx + c, m is the gradient and c is where the line crosses the y-axis.`],[7,3,`algebra`,`Which point lies on the line y = 2x?`,`(3, 6)`,[`(6, 3)`,`(2, 2)`,`(1, 3)`],`When x = 3, y = 2 × 3 = 6.`],[7,3,`algebra`,`A number divided by 4 gives 5. What is the number?`,`20`,[`1.25`,`9`,`1`],`Undo the division by multiplying: 5 × 4 = 20.`],[8,1,`algebra`,`Expand (x + 3)(x + 2).`,`x² + 5x + 6`,[`x² + 6x + 5`,`x² + 6`,`2x + 5`],`x × x + x × 2 + 3 × x + 3 × 2 = x² + 5x + 6.`],[8,1,`algebra`,`The graph of y = x² is a straight line.`,`False`,[`True`],`y = x² makes a U-shaped curve called a parabola.`],[8,2,`algebra`,`Solve the simultaneous equations x + y = 10 and x − y = 4.`,`x = 7, y = 3`,[`x = 6, y = 4`,`x = 3, y = 7`,`x = 5, y = 5`],`Adding the equations gives 2x = 14, so x = 7 and y = 3.`],[8,2,`algebra`,`Which values of x solve x² = 49?`,`7 and −7`,[`7 only`,`49 and −49`,`24.5`],`Both 7 × 7 and −7 × −7 equal 49.`],[8,3,`algebra`,`Factorise x² − 9.`,`(x + 3)(x − 3)`,[`(x − 3)²`,`(x + 9)(x − 1)`,`x(x − 9)`],`This is a difference of two squares: a² − b² = (a + b)(a − b).`],[8,3,`algebra`,`Rearrange v = u + at to make t the subject.`,`t = (v − u) ÷ a`,[`t = v − u − a`,`t = a ÷ (v − u)`,`t = (v + u) × a`],`Subtract u from both sides, then divide both sides by a.`],[3,1,`data`,`In a tally chart, a bundle of four lines with one line across them stands for…`,`5`,[`4`,`10`,`1`],`Tally marks are grouped in fives to make counting quick.`],[3,2,`data`,`A pictogram uses 1 picture for 2 children. How many children do 4 pictures show?`,`8`,[`4`,`6`,`2`],`Each picture stands for 2, so 4 pictures stand for 4 × 2 = 8.`],[3,2,`data`,`It is impossible to roll a 7 on an ordinary six-sided dice.`,`True`,[`False`],`The faces only go from 1 to 6.`],[3,3,`data`,`Which word describes something that will definitely happen?`,`Certain`,[`Impossible`,`Unlikely`,`Even chance`],`The Sun rising tomorrow is certain; rolling a 7 on a dice is impossible.`],[4,1,`data`,`Which chart compares amounts using rectangles of different heights?`,`A bar chart`,[`A pie chart`,`A line graph`,`A Venn diagram`],`The taller the bar, the bigger the amount.`],[4,2,`data`,`Five children scored 3, 5, 5, 6 and 1. What is the mode?`,`5`,[`4`,`6`,`1`],`The mode is the value that appears most often.`],[4,2,`data`,`A pie chart shows how a whole is split into parts.`,`True`,[`False`],`Each slice shows a fraction of the whole circle.`],[4,3,`data`,`When you toss a fair coin, what is the chance of getting heads?`,`1 in 2`,[`1 in 3`,`1 in 4`,`Certain`],`There are two equally likely outcomes, heads or tails.`],[5,1,`data`,`What is the range of 4, 9, 2 and 7?`,`7`,[`9`,`2`,`22`],`Range = largest − smallest = 9 − 2 = 7.`],[5,1,`data`,`On a probability scale, 0 means impossible.`,`True`,[`False`],`Probabilities go from 0 (impossible) to 1 (certain).`],[5,2,`data`,`What is the mean of 2, 4 and 6?`,`4`,[`12`,`6`,`2`],`Add them (12) and share the total equally among the 3 numbers: 12 ÷ 3 = 4.`],[5,2,`data`,`A bag holds 3 red balls and 1 blue ball. Which colour are you more likely to pick?`,`Red`,[`Blue`,`Both equally likely`,`Neither`],`There are three red chances and only one blue chance.`],[5,3,`data`,`What is the median of 3, 8, 1, 9 and 5?`,`5`,[`8`,`1`,`26`],`In order: 1, 3, 5, 8, 9. The middle value is 5.`],[6,1,`data`,`What is the probability of rolling a 6 on a fair six-sided dice?`,`1/6`,[`1/2`,`6/6`,`1/3`],`One face out of six equally likely faces.`],[6,1,`data`,`The probabilities of all the possible outcomes add up to 1.`,`True`,[`False`],`Something must happen, so all the chances together make a certainty.`],[6,2,`data`,`In a pie chart, what angle shows half of the data?`,`180°`,[`90°`,`360°`,`50°`],`The whole circle is 360°, so half is 180°.`],[6,2,`data`,`Which average is the middle value when the data are put in order?`,`The median`,[`The mean`,`The mode`,`The range`],`The median is the middle value. The mean adds and shares; the mode is the most common; the range is not an average.`],[6,3,`data`,`A spinner has 8 equal parts and 3 of them are green. What is the probability of green?`,`3/8`,[`3/5`,`5/8`,`1/3`],`3 green parts out of 8 equally likely parts.`],[7,1,`data`,`The chance that it rains tomorrow is 0.3. What is the chance that it does not rain?`,`0.7`,[`0.3`,`1.3`,`0.03`],`It either rains or it does not, so the two chances add up to 1: 1 − 0.3 = 0.7.`],[7,1,`data`,`An outlier is a value a long way from the rest of the data.`,`True`,[`False`],`One child who is 2 m tall in a class of 1.4 m children would be an outlier.`],[7,2,`data`,`Two fair coins are tossed. What is the probability of getting two heads?`,`1/4`,[`1/2`,`1/3`,`3/4`],`The outcomes HH, HT, TH and TT are equally likely, and only one is HH.`],[7,2,`data`,`A survey asks only people leaving a gym whether they exercise. What is wrong with it?`,`The sample is biased`,[`The sample is too random`,`The questions are too short`,`Gyms are always closed`],`People at a gym are more likely to exercise than people in general.`],[7,3,`data`,`What does a scatter graph show?`,`Whether two sets of data are related`,[`Parts of a whole`,`How often each value appears`,`The size of a single number`],`Each point plots two measurements, such as height and arm span.`],[7,3,`data`,`The mean of four numbers is 10. Three of them are 8, 9 and 12. What is the fourth?`,`11`,[`10`,`9`,`13`],`The four numbers add up to 4 × 10 = 40, and 40 − (8 + 9 + 12) = 11.`],[8,1,`data`,`A fair dice is rolled 600 times. About how many sixes would you expect?`,`100`,[`60`,`6`,`300`],`1/6 of 600 is 100; the real number will usually be close, not exact.`],[8,1,`data`,`When two things are correlated, one always causes the other.`,`False`,[`True`],`Ice-cream sales and sunburn rise together, but both are caused by sunny weather.`],[8,2,`data`,`Which correlation fits 'the more hours of revision, the higher the score'?`,`Positive correlation`,[`Negative correlation`,`No correlation`,`Perfect symmetry`],`Both values rise together.`],[8,2,`data`,`What does the interquartile range measure?`,`How spread out the middle half of the data is`,[`The single most common value`,`The total of all the values`,`The highest value only`],`It is the upper quartile minus the lower quartile, so outliers barely affect it.`],[8,3,`data`,`Two events are independent, with P(A) = 0.5 and P(B) = 0.2. What is P(A and B)?`,`0.1`,[`0.7`,`0.3`,`0.25`],`For independent events, multiply: 0.5 × 0.2 = 0.1.`],[8,3,`data`,`One very tall student changes a class's average height a lot. Which average is least affected?`,`The median`,[`The mean`,`The sum of the heights`,`The tallest height`],`The median depends only on the middle value, not on extreme ones.`]],[[3,1,`number`,`How many hundreds are in the number 700?`,`7`,[`70`,`700`,`1`],`700 is seven hundreds: 7 × 100 = 700.`],[3,1,`number`,`Which number is 10 more than 45?`,`55`,[`46`,`35`,`145`],`Adding ten raises the tens digit by one: 45 + 10 = 55.`],[3,1,`number`,`How is the number 19 written in words?`,`Nineteen`,[`Ninety`,`Nine`,`Ninety-one`],`19 is one ten and nine ones: nineteen. Ninety is 90.`],[3,1,`number`,`Odd numbers always end in 1, 3, 5, 7 or 9.`,`True`,[`False`],`A whole number is odd when its last digit is 1, 3, 5, 7 or 9.`],[3,2,`number`,`Count back in fives from 40. Which number do you say just after 30?`,`25`,[`35`,`20`,`29`],`Counting back in fives goes 40, 35, 30, 25.`],[3,2,`number`,`Which pair of numbers adds up to exactly 100?`,`64 and 36`,[`60 and 30`,`55 and 55`,`72 and 38`],`64 + 36 = 100. The other pairs make 90, 110 and 110.`],[3,2,`number`,`Sara has 3 bags with 5 sweets in each. How many sweets is that altogether?`,`15`,[`8`,`35`,`12`],`Three groups of five: 3 × 5 = 15.`],[3,2,`number`,`24 stickers are shared equally among 4 friends. How many does each friend get?`,`6`,[`4`,`20`,`8`],`24 ÷ 4 = 6, because 4 × 6 = 24.`],[3,3,`number`,`What is the largest 3-digit number whose digits are all different?`,`987`,[`999`,`789`,`900`],`Use the three biggest different digits, largest first: 9, 8, 7.`],[3,3,`number`,`Which number lies exactly halfway between 20 and 30?`,`25`,[`24`,`15`,`50`],`20 and 30 are 10 apart; half of 10 is 5, and 20 + 5 = 25.`],[3,3,`number`,`If you double a number and then halve the answer, you get back the number you started with.`,`True`,[`False`],`Halving undoes doubling: double 7 is 14, and half of 14 is 7.`],[3,3,`number`,`A bus has 52 seats and 37 people are sitting down. How many seats are empty?`,`15`,[`25`,`89`,`14`],`52 − 37 = 15 empty seats.`],[4,1,`number`,`What is 7 × 8?`,`56`,[`54`,`48`,`63`],`Seven eights are 56; check with 8 × 7 = 56.`],[4,1,`number`,`Which digit is in the thousands place in 6,429?`,`6`,[`4`,`2`,`9`],`In 6,429 the digits stand for 6 thousands, 4 hundreds, 2 tens and 9 ones.`],[4,1,`number`,`Any number multiplied by 1 stays the same.`,`True`,[`False`],`Multiplying by 1 means taking one lot of the number, so 9 × 1 = 9.`],[4,2,`number`,`Which number is a common multiple of 3 and 4?`,`24`,[`14`,`16`,`18`],`24 = 3 × 8 and 24 = 4 × 6. 16 is not a multiple of 3, and 14 and 18 are not multiples of 4.`],[4,2,`number`,`Which Roman numeral is 9?`,`IX`,[`VIIII`,`XI`,`VIX`],`I before X means one less than ten: IX = 9. XI is 11.`],[4,2,`number`,`A cook buys 4 boxes with 12 eggs in each. How many eggs is that?`,`48`,[`16`,`36`,`412`],`4 × 12 = 48 eggs.`],[4,2,`number`,`What is the remainder when 29 is divided by 5?`,`4`,[`5`,`9`,`3`],`5 × 5 = 25 and 29 − 25 = 4, so the remainder is 4.`],[4,3,`number`,`Which is the best estimate of 398 + 203?`,`600`,[`500`,`700`,`400`],`398 is about 400 and 203 is about 200, so the total is about 600.`],[4,3,`number`,`A number is odd, lies between 40 and 50, and its digits add up to 13. What is it?`,`49`,[`47`,`45`,`58`],`4 + 9 = 13, and 49 is odd. 58 is outside the range.`],[4,3,`number`,`If you have 0 groups of 8 counters, you have 8 counters.`,`False`,[`True`],`Zero groups of anything is nothing at all: 0 × 8 = 0.`],[5,1,`number`,`How many thousands are there in one million?`,`1,000`,[`100`,`10,000`,`10`],`1,000 × 1,000 = 1,000,000.`],[5,1,`number`,`Which of these is a square number?`,`49`,[`40`,`24`,`18`],`49 = 7 × 7, so it is a square number.`],[5,1,`number`,`Take one away from a thousand. What number is left?`,`999`,[`900`,`1,001`,`990`],`One less than one thousand is nine hundred and ninety-nine.`],[5,2,`number`,`What is 6 squared plus 4 squared?`,`52`,[`20`,`100`,`48`],`6² = 36 and 4² = 16, so 36 + 16 = 52.`],[5,2,`number`,`It is 2 °C, and the temperature drops by 5 degrees. What is the temperature now?`,`−3 °C`,[`3 °C`,`−7 °C`,`7 °C`],`Count down 5 from 2, passing 0: 1, 0, −1, −2, −3.`],[5,2,`number`,`What is 3,456 rounded to the nearest thousand?`,`3,000`,[`4,000`,`3,500`,`3,460`],`The hundreds digit is 4 (less than 5), so it rounds down to 3,000.`],[5,2,`number`,`Which number has exactly two factors?`,`13`,[`15`,`1`,`9`],`13 is prime: its only factors are 1 and 13. The number 1 has just one factor.`],[5,3,`number`,`A school orders 375 books, packed 25 to a box. How many boxes arrive?`,`15`,[`14`,`350`,`25`],`375 ÷ 25 = 15, because 25 × 15 = 375.`],[5,3,`number`,`Which of these numbers is divisible by 9?`,`5,148`,[`5,147`,`4,321`,`6,104`],`A number divides by 9 when its digits add to a multiple of 9: 5 + 1 + 4 + 8 = 18.`],[5,3,`number`,`Every whole number ending in 0 or 5 can be divided exactly by 5.`,`True`,[`False`],`Multiples of 5 always end in 0 or 5, for example 35 = 5 × 7 and 40 = 5 × 8.`],[6,1,`number`,`What is the value of 2⁵?`,`32`,[`10`,`25`,`64`],`2 × 2 × 2 × 2 × 2 = 32.`],[6,1,`number`,`Which is the smallest prime number?`,`2`,[`1`,`3`,`0`],`2 is the smallest prime (and the only even one); 1 is not prime.`],[6,1,`number`,`A diver is 7 m below the surface (−7 m) and rises 3 m. What is the diver's new position?`,`−4 m`,[`−10 m`,`4 m`,`10 m`],`Rising 3 m from −7 m gives −7 + 3 = −4 m, still below the surface.`],[6,2,`number`,`Using the correct order of operations, what is 2 + 3 × 4?`,`14`,[`20`,`24`,`9`],`Multiplication comes before addition: 3 × 4 = 12, then 2 + 12 = 14.`],[6,2,`number`,`Two buses leave a station together. One returns every 12 minutes and the other every 18 minutes. After how many minutes are both back together?`,`36`,[`30`,`216`,`6`],`36 is the lowest common multiple of 12 and 18 (12 × 3 = 18 × 2 = 36).`],[6,2,`number`,`Ribbons of 24 cm and 36 cm are cut into equal pieces with nothing left over. What is the longest each piece can be?`,`12 cm`,[`6 cm`,`4 cm`,`72 cm`],`12 is the highest common factor of 24 and 36: 24 = 2 × 12 and 36 = 3 × 12.`],[6,2,`number`,`What is the reciprocal of 4?`,`1/4`,[`−4`,`0.4`,`16`],`A number times its reciprocal makes 1, and 4 × 1/4 = 1.`],[6,3,`number`,`A lift goes from floor 3 down to basement level −2. How many floors does it travel?`,`5`,[`1`,`−5`,`6`],`From 3 down to −2 is 3 − (−2) = 5 floors.`],[6,3,`number`,`What is the smallest number that has exactly three factors?`,`4`,[`3`,`6`,`9`],`4 has the factors 1, 2 and 4. Three has two factors and six has four; nine also has three but is bigger.`],[6,3,`number`,`Every prime number greater than 2 is odd.`,`True`,[`False`],`Any even number above 2 can be divided by 2, so it cannot be prime.`],[7,1,`number`,`What do you get when 3.7 is made 100 times larger?`,`370`,[`37`,`3,700`,`0.037`],`Multiplying by 100 moves each digit two places to the left: 3.7 → 370.`],[7,1,`number`,`Round 2.786 to two decimal places.`,`2.79`,[`2.78`,`2.8`,`2.786`],`The third decimal digit is 6, so the second rounds up from 8 to 9.`],[7,1,`number`,`The square of a negative number is negative.`,`False`,[`True`],`Negative times negative is positive: (−5)² = 25.`],[7,2,`number`,`Round 0.04528 to 2 significant figures.`,`0.045`,[`0.04`,`0.0453`,`0.05`],`Leading zeros do not count; the first two significant figures are 4 and 5, and the next digit (2) rounds down.`],[7,2,`number`,`Which of these is a cube number?`,`125`,[`100`,`150`,`36`],`125 = 5 × 5 × 5.`],[7,2,`number`,`Between which two whole numbers does √50 lie?`,`7 and 8`,[`6 and 7`,`25 and 26`,`49 and 51`],`7² = 49 and 8² = 64, so √50 is just over 7.`],[7,3,`number`,`How many factors does 36 have?`,`9`,[`8`,`6`,`12`],`1, 2, 3, 4, 6, 9, 12, 18 and 36: nine factors (6 pairs with itself).`],[7,3,`number`,`Estimate 49.8 × 3.1 by rounding each number to 1 significant figure.`,`150`,[`120`,`160`,`200`],`49.8 is about 50 and 3.1 is about 3, so the estimate is 50 × 3 = 150.`],[7,3,`number`,`Compare 2⁶, 4³ and 8². Which one is the largest?`,`They are all equal`,[`2⁶`,`4³`,`8²`],`2⁶ = 64, 4³ = 64 and 8² = 64.`],[8,1,`number`,`Which number, multiplied by itself, gives 0.25?`,`0.5`,[`0.05`,`0.125`,`2.5`],`0.5 × 0.5 = 0.25.`],[8,1,`number`,`Using the index laws, write 5⁶ ÷ 5² as a single power of 5.`,`5⁴`,[`5³`,`5⁸`,`1⁴`],`When dividing powers of the same number, subtract the indices: 6 − 2 = 4.`],[8,1,`number`,`Every recurring decimal can be written as a fraction.`,`True`,[`False`],`Recurring decimals are rational: 0.333… = 1/3 and 0.1212… = 12/99.`],[8,2,`number`,`Write √12 in its simplest surd form.`,`2√3`,[`3√2`,`6`,`4√3`],`√12 = √(4 × 3) = √4 × √3 = 2√3.`],[8,2,`number`,`What is (2³)²?`,`64`,[`32`,`12`,`2⁵`],`A power of a power multiplies the indices: (2³)² = 2⁶ = 64.`],[8,2,`number`,`Write 0.00056 in standard form.`,`5.6 × 10⁻⁴`,[`5.6 × 10⁴`,`56 × 10⁻⁵`,`5.6 × 10⁻³`],`Move the decimal point 4 places right to get 5.6, so the power is −4.`],[8,2,`number`,`Work out (3 × 10⁴) × (2 × 10³) in standard form.`,`6 × 10⁷`,[`6 × 10¹²`,`5 × 10⁷`,`6 × 10⁶`],`Multiply 3 × 2 = 6 and add the powers: 10⁴ × 10³ = 10⁷.`],[8,3,`number`,`Which of these fractions gives a decimal that ends (terminates)?`,`7/20`,[`1/3`,`2/7`,`5/6`],`7/20 = 0.35. A fraction in lowest terms terminates when its denominator has no prime factors except 2 and 5.`],[8,3,`number`,`What is 8 to the power ⅔?`,`4`,[`5.33`,`16`,`2`],`The cube root of 8 is 2, and 2 squared is 4.`],[8,3,`number`,`√2 × √2 is a rational number.`,`True`,[`False`],`√2 × √2 = 2, which is a whole number, so it is rational.`],[3,1,`fractions`,`What is one quarter of 20?`,`5`,[`4`,`10`,`80`],`Split 20 into four equal groups: 20 ÷ 4 = 5.`],[3,2,`fractions`,`Three-quarters of 4 cupcakes have icing on top. How many cupcakes have icing?`,`3`,[`1`,`4`,`2`],`One quarter of 4 is 1, so three quarters is 3.`],[3,3,`fractions`,`Two quarters make a half.`,`True`,[`False`],`2/4 is the same amount as 1/2.`],[3,3,`fractions`,`Lee eats 2/6 of a pizza and Kim eats 3/6. How much of the pizza is left?`,`1/6`,[`5/6`,`1/3`,`2/6`],`Together they eat 5/6, so 6/6 − 5/6 = 1/6 is left.`],[4,2,`fractions`,`Ravi has 20 marbles and gives away 1/4 of them. How many marbles are left?`,`15`,[`5`,`16`,`4`],`A quarter of 20 is 5, so 20 − 5 = 15 are left.`],[4,2,`fractions`,`What is 7/10 written as a decimal?`,`0.7`,[`7.10`,`0.07`,`1.7`],`Seven tenths is 0.7: the 7 sits in the tenths place.`],[4,3,`fractions`,`Which two fractions are equivalent?`,`2/3 and 4/6`,[`2/3 and 3/4`,`1/2 and 2/3`,`3/5 and 5/3`],`Doubling the top and bottom of 2/3 gives 4/6, so they are equal.`],[4,3,`fractions`,`Subtract 3/8 from 1 whole.`,`5/8`,[`3/8`,`2/8`,`4/8`],`One whole is 8/8, and 8/8 − 3/8 = 5/8.`],[4,3,`fractions`,`When the top number is 1, a bigger bottom number gives a bigger fraction.`,`False`,[`True`],`Sharing among more people gives smaller pieces: 1/10 is less than 1/2.`],[5,1,`fractions`,`Find ten per cent of 250 taka.`,`25 taka`,[`2.5 taka`,`250 taka`,`10 taka`],`10 % is one tenth, and 250 ÷ 10 = 25.`],[5,1,`fractions`,`Which fraction of an hour is 15 minutes?`,`1/4`,[`1/15`,`1/2`,`1/6`],`An hour is 60 minutes, and 15 is a quarter of 60.`],[5,2,`fractions`,`Half a litre of milk and a third of a litre of milk are poured into a jug. How much milk is in the jug?`,`5/6 of a litre`,[`2/5 of a litre`,`1/5 of a litre`,`2/6 of a litre`],`Use sixths: 1/2 = 3/6 and 1/3 = 2/6, so 3/6 + 2/6 = 5/6.`],[5,2,`fractions`,`Which improper fraction is the same as 1¾?`,`7/4`,[`4/7`,`13/4`,`3/4`],`One whole is 4/4, and 4/4 + 3/4 = 7/4.`],[5,2,`fractions`,`A jug holds 2 litres. How much is three-quarters of the jug?`,`1.5 litres`,[`0.75 litres`,`1.25 litres`,`2.75 litres`],`A quarter of 2 litres is 0.5 litres, so three quarters is 1.5 litres.`],[5,3,`fractions`,`Put these in order from smallest to largest: 3/5, 0.55, 58 %.`,`0.55, 58 %, 3/5`,[`3/5, 0.55, 58 %`,`58 %, 3/5, 0.55`,`0.55, 3/5, 58 %`],`As decimals they are 0.6, 0.55 and 0.58, so the order is 0.55, 0.58, 0.6.`],[5,3,`fractions`,`A class of 30 has 12 girls. What fraction of the class are girls, in its simplest form?`,`2/5`,[`12/30`,`1/3`,`3/5`],`12/30 simplifies by dividing top and bottom by 6: 2/5.`],[5,3,`fractions`,`0.5, 50 % and ½ all stand for the same amount.`,`True`,[`False`],`Half is 0.5 as a decimal and 50 out of 100 as a percentage.`],[6,1,`fractions`,`What is 1/4 + 0.25 written as a decimal?`,`0.5`,[`0.125`,`0.75`,`1.25`],`1/4 is 0.25, and 0.25 + 0.25 = 0.5.`],[6,1,`fractions`,`What is 35 % as a fraction in its simplest form?`,`7/20`,[`35/10`,`3/5`,`7/10`],`35 % = 35/100, and dividing top and bottom by 5 gives 7/20.`],[6,1,`fractions`,`Dividing a number by one half is the same as doubling it.`,`True`,[`False`],`There are two halves in every whole, so 6 ÷ ½ = 12.`],[6,2,`fractions`,`A recipe for 4 people uses 300 g of rice. How much rice is needed for 6 people?`,`450 g`,[`500 g`,`200 g`,`600 g`],`Each person needs 300 ÷ 4 = 75 g, and 6 × 75 g = 450 g.`],[6,2,`fractions`,`Two amounts are in the ratio 4 : 5, and the smaller one is 20. What is the larger one?`,`25`,[`20`,`9`,`36`],`4 parts are 20, so 1 part is 5 and 5 parts are 25.`],[6,2,`fractions`,`Calculate 0.3 × 0.2.`,`0.06`,[`0.6`,`0.006`,`6`],`3 × 2 = 6, and there are two decimal places in the question, so 0.06.`],[6,2,`fractions`,`Convert three-eighths into a decimal.`,`0.375`,[`0.38`,`3.8`,`0.0375`],`3 ÷ 8 = 0.375 (an eighth is 0.125).`],[6,3,`fractions`,`A jacket's price is cut from 800 taka to 680 taka. By what percentage was it cut?`,`15 %`,[`12 %`,`120 %`,`85 %`],`The cut is 120 taka, and 120/800 = 0.15 = 15 %.`],[6,3,`fractions`,`Divide 3/4 by 3.`,`1/4`,[`9/4`,`1/12`,`3/7`],`Splitting three quarters into 3 equal parts gives one quarter each.`],[7,1,`fractions`,`A plant is 50 cm tall and grows to 120 % of that height. How tall is it now?`,`60 cm`,[`70 cm`,`170 cm`,`62 cm`],`120 % of 50 = 1.2 × 50 = 60 cm.`],[7,1,`fractions`,`Write 0.8 as a fraction in its simplest form.`,`4/5`,[`8/10`,`1/8`,`2/5`],`0.8 = 8/10, and dividing top and bottom by 2 gives 4/5.`],[7,1,`fractions`,`Increasing a price by 10 % and then by another 10 % is the same as increasing it by 20 %.`,`False`,[`True`],`The second rise is 10 % of a bigger amount: 1.1 × 1.1 = 1.21, a rise of 21 %.`],[7,2,`fractions`,`2,000 taka is saved at 5 % simple interest a year. How much interest is earned in 3 years?`,`300 taka`,[`100 taka`,`315.25 taka`,`3,000 taka`],`Each year earns 5 % of 2,000 = 100 taka, and 3 years earn 300 taka.`],[7,2,`fractions`,`4 workers build a wall in 6 days. Working at the same rate, how long would 8 workers take?`,`3 days`,[`12 days`,`2 days`,`4 days`],`Twice as many workers need half the time: 6 ÷ 2 = 3 days.`],[7,2,`fractions`,`Suppose 1 US dollar is worth 110 taka. How many taka are 15 dollars worth?`,`1,650 taka`,[`1,500 taka`,`125 taka`,`1,100 taka`],`15 × 110 = 1,650 taka.`],[7,3,`fractions`,`Write the ratio 1.5 : 2.5 in its simplest whole-number form.`,`3 : 5`,[`15 : 25`,`1 : 2`,`2 : 3`],`Double both parts to get 3 : 5, which cannot be simplified further.`],[7,3,`fractions`,`A shop buys a toy for 250 taka and sells it for 300 taka. What is the percentage profit?`,`20 %`,[`50 %`,`16.7 %`,`25 %`],`The profit is 50 taka, and 50/250 = 0.2 = 20 % of the cost price.`],[7,3,`fractions`,`How many times does 4/9 fit into 2/3?`,`3/2`,[`8/27`,`2/3`,`6/13`],`Multiply by the reciprocal: 2/3 × 9/4 = 18/12 = 3/2.`],[8,1,`fractions`,`Which decimal multiplier increases an amount by 15 %?`,`1.15`,[`0.15`,`1.5`,`0.85`],`The new amount is 100 % + 15 % = 115 % of the old one, which is × 1.15.`],[8,2,`fractions`,`y is directly proportional to x, and y = 12 when x = 3. What is y when x = 5?`,`20`,[`15`,`14`,`36`],`y = 4x, because 12 = 4 × 3. So when x = 5, y = 20.`],[8,2,`fractions`,`A trip takes 6 hours at 40 km/h. How long does the same trip take at 60 km/h?`,`4 hours`,[`9 hours`,`5 hours`,`3 hours`],`The distance is 6 × 40 = 240 km, and 240 ÷ 60 = 4 hours.`],[8,2,`fractions`,`A colony of 1,000 bacteria doubles every hour. How many bacteria are there after 4 hours?`,`16,000`,[`8,000`,`4,000`,`5,000`],`Doubling four times multiplies by 2⁴ = 16: 1,000 × 16 = 16,000.`],[8,3,`fractions`,`A car worth 500,000 taka loses 10 % of its value each year. What will it be worth after 2 years?`,`405,000 taka`,[`400,000 taka`,`450,000 taka`,`410,000 taka`],`Each year multiply by 0.9: 500,000 × 0.9 × 0.9 = 405,000.`],[8,3,`fractions`,`Prices rise by 25 %. By what percentage must they then fall to get back to where they started?`,`20 %`,[`25 %`,`75 %`,`15 %`],`1.25 × 0.8 = 1, and multiplying by 0.8 is a 20 % fall.`],[8,3,`fractions`,`If a : b = 2 : 3, then b is one and a half times a.`,`True`,[`False`],`b/a = 3/2 = 1.5, so b is 1.5 times a.`]],[[3,1,`geometry`,`A square sandwich is cut from one corner to the opposite corner. What shape is each half?`,`A triangle`,[`A square`,`A rectangle`,`A circle`],`Cutting along a diagonal splits the square into two halves, and each half is a triangle with three sides.`],[3,1,`geometry`,`Which flat shape has one curved edge and one straight edge, like half a round pizza?`,`A semicircle`,[`A triangle`,`A quarter`,`An oval`],`Cutting a circle along its diameter makes two semicircles, each with one curved and one straight edge.`],[3,2,`geometry`,`Which 3D shape looks like an ice-cream cone?`,`A cone`,[`A cylinder`,`A cube`,`A pyramid`],`A cone has a circular base and narrows to a single point.`],[3,2,`geometry`,`A rectangle has two lines of symmetry.`,`True`,[`False`],`One line runs across the middle and one runs down the middle. The diagonals are not lines of symmetry.`],[3,3,`geometry`,`How many edges does a cube have?`,`12`,[`6`,`8`,`4`],`A cube has 4 edges round the top, 4 round the bottom and 4 going up the sides: 12.`],[3,3,`geometry`,`Which shape is made by two right angles placed side by side on a straight line?`,`A straight angle`,[`An acute angle`,`A full turn`,`A reflex angle`],`Two right angles make 90° + 90° = 180°, which is a straight line.`],[4,1,`geometry`,`Which of these shapes is a quadrilateral (has four straight sides)?`,`A kite`,[`A triangle`,`A pentagon`,`A circle`],`Quad means four: a kite has four straight sides, like squares, rectangles and trapeziums.`],[4,1,`geometry`,`What kind of angle is bigger than 180° but less than 360°?`,`Reflex`,[`Obtuse`,`Acute`,`Right`],`Reflex angles are more than a half turn but less than a full turn.`],[4,2,`geometry`,`How many vertices (corners) does a square-based pyramid have?`,`5`,[`4`,`6`,`8`],`Four corners round the square base plus one at the top: 5.`],[4,2,`geometry`,`A triangle with two equal sides and two equal angles is called…`,`isosceles`,[`scalene`,`equilateral`,`right-angled`],`An isosceles triangle has two equal sides, and the angles opposite them are equal too.`],[4,2,`geometry`,`Perpendicular lines meet at a right angle.`,`True`,[`False`],`Perpendicular lines cross or meet at exactly 90°, like the corner of a page.`],[4,3,`geometry`,`Which net folds up to make a cube?`,`A cross of six squares`,[`A row of five squares`,`Four triangles and a square`,`Two circles and a rectangle`],`A cube has six square faces; a cross shape of six squares folds into one.`],[4,3,`geometry`,`On a grid, the point (4, 1) is 4 squares across. How far up is it?`,`1 square`,[`4 squares`,`5 squares`,`3 squares`],`Coordinates are written (across, up), so (4, 1) is 1 square up.`],[5,1,`geometry`,`Which quadrilateral has two pairs of parallel sides and no right angles?`,`A parallelogram`,[`A trapezium`,`A kite`,`A rectangle`],`A parallelogram has opposite sides parallel; unless its angles are 90° it is not a rectangle.`],[5,1,`geometry`,`What do the angles round a point add up to?`,`360°`,[`180°`,`90°`,`270°`],`Going all the way round a point is one full turn: 360°.`],[5,2,`geometry`,`Two angles of a triangle are 50° and 60°. What is the third angle?`,`70°`,[`80°`,`90°`,`110°`],`The three angles add to 180°: 180° − 50° − 60° = 70°.`],[5,2,`geometry`,`What is the order of rotational symmetry of a square?`,`4`,[`2`,`1`,`8`],`A square looks the same 4 times in one full turn: after every quarter turn.`],[5,2,`geometry`,`A kite has two pairs of equal sides that are next to each other.`,`True`,[`False`],`In a kite the equal sides are adjacent, unlike a parallelogram where they are opposite.`],[5,3,`geometry`,`Which shapes fit together with no gaps to cover a floor (tessellate) on their own?`,`Regular hexagons`,[`Regular pentagons`,`Circles`,`Regular octagons`],`Each angle of a regular hexagon is 120°, and three of them make 360° at a point.`],[5,3,`geometry`,`In which quadrant is the point (−3, 2)?`,`Second`,[`First`,`Third`,`Fourth`],`x is negative and y is positive: up and to the left, the second quadrant.`],[6,1,`geometry`,`A straight line joining two points on a circle (not through the centre) is called a…`,`chord`,[`radius`,`tangent`,`sector`],`A chord joins two points on the circle; the diameter is the longest chord.`],[6,1,`geometry`,`How many lines of symmetry does an equilateral triangle have?`,`3`,[`1`,`6`,`0`],`Each line runs from a corner to the middle of the opposite side.`],[6,2,`geometry`,`A line that touches a circle at just one point is called a…`,`tangent`,[`chord`,`diameter`,`segment`],`A tangent just touches the circle, at right angles to the radius there.`],[6,2,`geometry`,`Faces + vertices − edges = 2 for any solid with flat faces like a cube. What is this rule called?`,`Euler's formula`,[`Pythagoras' theorem`,`The angle sum`,`The area rule`],`For a cube, 6 + 8 − 12 = 2. Euler's formula works for every polyhedron without holes.`],[6,2,`geometry`,`Which transformation turns a shape about a fixed point?`,`A rotation`,[`A translation`,`A reflection`,`An enlargement`],`A rotation turns a shape through an angle about a centre.`],[6,3,`geometry`,`An exterior angle of a triangle is 110°. One of the two opposite interior angles is 40°. What is the other?`,`70°`,[`30°`,`150°`,`110°`],`An exterior angle equals the sum of the two opposite interior angles: 110° − 40° = 70°.`],[6,3,`geometry`,`Point A is at (2, 3) and point B is at (8, 7). What is the midpoint of AB?`,`(5, 5)`,[`(6, 4)`,`(10, 10)`,`(3, 2)`],`Average the coordinates: ((2 + 8) ÷ 2, (3 + 7) ÷ 2) = (5, 5).`],[7,1,`geometry`,`Moving a shape 3 squares right and 2 squares up without turning it is a…`,`translation`,[`rotation`,`reflection`,`enlargement`],`A translation slides a shape; its size and direction stay the same.`],[7,1,`geometry`,`Every square is also a rhombus.`,`True`,[`False`],`A rhombus has four equal sides; a square does too, with right angles as well.`],[7,2,`geometry`,`A regular polygon has exterior angles of 30°. How many sides does it have?`,`12`,[`30`,`6`,`10`],`The exterior angles of any polygon add to 360°, and 360° ÷ 30° = 12.`],[7,2,`geometry`,`Which three lengths could be the sides of a right-angled triangle?`,`6, 8 and 10`,[`5, 6 and 7`,`2, 3 and 4`,`4, 4 and 7`],`Pythagoras works only for right angles: 6² + 8² = 36 + 64 = 100 = 10². For the others the squares do not add up.`],[7,2,`geometry`,`A ship sails on a bearing of 090°. In which direction is it going?`,`East`,[`North`,`South`,`West`],`Bearings are measured clockwise from north, so 090° is a quarter turn: east.`],[7,3,`geometry`,`The bearing of B from A is 060°. What is the bearing of A from B?`,`240°`,[`060°`,`120°`,`300°`],`A back bearing differs by 180°: 60° + 180° = 240°.`],[7,3,`geometry`,`The set of all points exactly 3 cm from a fixed point forms…`,`a circle of radius 3 cm`,[`a square of side 3 cm`,`a line 3 cm long`,`a circle of radius 6 cm`],`Every point on a circle is the same distance (the radius) from its centre.`],[8,1,`geometry`,`In a right-angled triangle, sin of an angle equals…`,`opposite ÷ hypotenuse`,[`adjacent ÷ hypotenuse`,`opposite ÷ adjacent`,`hypotenuse ÷ opposite`],`SOH: sine = opposite ÷ hypotenuse (cos uses adjacent, and tan is opposite ÷ adjacent).`],[8,1,`geometry`,`What is tan 45°?`,`1`,[`0`,`0.5`,`√2`],`In a right-angled triangle with a 45° angle, the opposite and adjacent sides are equal, so tan 45° = 1.`],[8,2,`geometry`,`What is the value of sin 30°?`,`0.5`,[`1`,`0.866`,`0`],`Half an equilateral triangle shows that the side opposite 30° is half the hypotenuse.`],[8,2,`geometry`,`Angles in the same segment of a circle are equal.`,`True`,[`False`],`Angles at the circumference standing on the same arc (chord) are equal: a circle theorem.`],[8,2,`geometry`,`The angle at the centre of a circle is 100°. What is the angle at the circumference standing on the same arc?`,`50°`,[`100°`,`200°`,`80°`],`The angle at the centre is twice the angle at the circumference: 100° ÷ 2 = 50°.`],[8,3,`geometry`,`Opposite angles of a cyclic quadrilateral add up to…`,`180°`,[`90°`,`360°`,`120°`],`If all four corners lie on a circle, each pair of opposite angles adds to 180°.`],[8,3,`geometry`,`A ladder 10 m long leans against a wall with its foot 6 m from the wall. How high up the wall does it reach?`,`8 m`,[`4 m`,`16 m`,`11.7 m`],`Pythagoras: 10² − 6² = 100 − 36 = 64, and √64 = 8 m.`],[3,1,`measurement`,`Which month usually has the fewest days?`,`February`,[`April`,`June`,`November`],`February has 28 days (29 in a leap year); April, June and November have 30.`],[3,1,`measurement`,`Which is heavier: 1 kilogram or 500 grams?`,`1 kilogram`,[`500 grams`,`They are equal`,`It depends on the object`],`1 kilogram is 1,000 grams, which is twice as heavy as 500 grams.`],[3,2,`measurement`,`A ribbon is 1 metre long. You cut off 35 cm. How much is left?`,`65 cm`,[`35 cm`,`75 cm`,`165 cm`],`1 metre is 100 cm, and 100 − 35 = 65 cm.`],[3,2,`measurement`,`A coin of 5 taka and a note of 20 taka make how much money?`,`25 taka`,[`15 taka`,`520 taka`,`205 taka`],`5 + 20 = 25 taka.`],[3,3,`measurement`,`School starts at 9:00 and lunch is 3 hours later. When is lunch?`,`12:00`,[`11:00`,`13:00`,`3:00`],`Count on three hours from 9:00: 10:00, 11:00, 12:00.`],[3,3,`measurement`,`April, June, September and November each have 30 days.`,`True`,[`False`],`‘Thirty days hath September, April, June and November’ is a rhyme for remembering this.`],[4,1,`measurement`,`Which of these holds about 1 litre?`,`A large water bottle`,[`A teaspoon`,`A bath tub`,`A raindrop`],`A large water bottle holds about a litre; a teaspoon holds about 5 ml and a bath about 150 litres.`],[4,1,`measurement`,`How many hours are there in 3 days?`,`72`,[`36`,`24`,`60`],`Each day has 24 hours: 3 × 24 = 72.`],[4,2,`measurement`,`How many seconds are there in one hour?`,`3,600`,[`60`,`360`,`6,000`],`60 seconds × 60 minutes = 3,600 seconds.`],[4,2,`measurement`,`What is 19:30 in 12-hour clock time?`,`7:30 pm`,[`9:30 pm`,`7:30 am`,`1:30 pm`],`Take away 12 from hours after noon: 19 − 12 = 7, so 7:30 pm.`],[4,3,`measurement`,`A 2-litre bottle fills glasses of 250 ml. How many glasses can be filled?`,`8`,[`4`,`10`,`6`],`2 litres is 2,000 ml, and 2,000 ÷ 250 = 8.`],[4,3,`measurement`,`A fortnight is two weeks, which is 14 days.`,`True`,[`False`],`‘Fortnight’ comes from ‘fourteen nights’.`],[5,1,`measurement`,`How many millimetres are in 4.5 cm?`,`45`,[`450`,`4.5`,`0.45`],`1 cm = 10 mm, so 4.5 cm = 45 mm.`],[5,2,`measurement`,`A rectangle has an area of 36 cm² and a length of 9 cm. How wide is it?`,`4 cm`,[`27 cm`,`6 cm`,`3 cm`],`Area = length × width, so width = 36 ÷ 9 = 4 cm.`],[5,2,`measurement`,`A parcel weighs 2.4 kg. What is that in grams?`,`2,400 g`,[`240 g`,`24 g`,`24,000 g`],`1 kg = 1,000 g, so 2.4 × 1,000 = 2,400 g.`],[5,3,`measurement`,`A train leaves at 10:45 and arrives at 13:20. How long is the journey?`,`2 hours 35 minutes`,[`3 hours 25 minutes`,`2 hours 25 minutes`,`3 hours 35 minutes`],`10:45 to 13:00 is 2 h 15 min, and 13:00 to 13:20 is 20 min more: 2 h 35 min.`],[5,3,`measurement`,`Two rectangles can have the same area but different perimeters.`,`True`,[`False`],`A 1 × 12 and a 3 × 4 rectangle both have area 12, but perimeters 26 and 14.`],[6,1,`measurement`,`What is the area of a parallelogram with base 8 cm and perpendicular height 5 cm?`,`40 cm²`,[`26 cm²`,`20 cm²`,`13 cm²`],`Area of a parallelogram = base × perpendicular height = 8 × 5 = 40 cm².`],[6,1,`measurement`,`About how many kilometres is 1 mile?`,`1.6`,[`0.6`,`2.5`,`1`],`One mile is about 1.6 km, so 5 miles is about 8 km.`],[6,2,`measurement`,`A trapezium has parallel sides of 6 cm and 10 cm and a height of 4 cm. What is its area?`,`32 cm²`,[`64 cm²`,`40 cm²`,`20 cm²`],`Area = ½ × (6 + 10) × 4 = 32 cm².`],[6,2,`measurement`,`At sea level, water boils at what temperature in degrees Fahrenheit?`,`212 °F`,[`100 °F`,`180 °F`,`32 °F`],`100 °C equals 212 °F; on the Fahrenheit scale water freezes at 32 °F.`],[6,3,`measurement`,`How many litres of water fill a tank of 1 cubic metre?`,`1,000`,[`100`,`10`,`10,000`],`1 m³ = 100 × 100 × 100 cm³ = 1,000,000 cm³, and 1,000 cm³ is 1 litre.`],[6,3,`measurement`,`A cyclist rides at 18 km/h. What is that in metres per second?`,`5 m/s`,[`18 m/s`,`3.6 m/s`,`50 m/s`],`18 km/h = 18,000 m per 3,600 s = 5 m/s.`],[7,1,`measurement`,`A triangular prism has a cross-section of 6 cm² and a length of 10 cm. What is its volume?`,`60 cm³`,[`16 cm³`,`600 cm³`,`30 cm³`],`Volume of a prism = area of cross-section × length = 6 × 10 = 60 cm³.`],[7,2,`measurement`,`What is the perimeter of a semicircle with diameter 10 cm? (Use π ≈ 3.14.)`,`25.7 cm`,[`15.7 cm`,`31.4 cm`,`20.7 cm`],`The curved part is half of 31.4 = 15.7 cm, plus the straight 10 cm diameter: 25.7 cm.`],[7,2,`measurement`,`A force of 50 newtons presses on an area of 2 m². What is the pressure?`,`25 N/m²`,[`100 N/m²`,`52 N/m²`,`48 N/m²`],`Pressure = force ÷ area = 50 ÷ 2 = 25 N/m² (25 pascals).`],[7,3,`measurement`,`On a plan, 1 cm stands for 2 m. A room is 4 cm by 3 cm on the plan. What is its real area?`,`48 m²`,[`12 m²`,`24 m²`,`14 m²`],`The real room is 8 m by 6 m, so its area is 48 m². (Areas scale by 2² = 4.)`],[7,3,`measurement`,`A square has an area of 1 km². How many square metres is that?`,`1,000,000 m²`,[`1,000 m²`,`100,000 m²`,`10,000 m²`],`1 km² = 1,000 m × 1,000 m = 1,000,000 m².`],[8,1,`measurement`,`An arc is cut off by an angle of 90° at the centre of a circle of radius 4 cm. How long is the arc? (Use π ≈ 3.14.)`,`6.28 cm`,[`12.56 cm`,`25.12 cm`,`3.14 cm`],`90° is a quarter of the circle: ¼ × 2 × 3.14 × 4 = 6.28 cm.`],[8,2,`measurement`,`A cone has a base area of 30 cm² and a height of 10 cm. What is its volume?`,`100 cm³`,[`300 cm³`,`150 cm³`,`40 cm³`],`Volume of a cone = ⅓ × base area × height = ⅓ × 30 × 10 = 100 cm³.`],[8,2,`measurement`,`Two similar boxes have lengths in the ratio 1 : 2. What is the ratio of their volumes?`,`1 : 8`,[`1 : 2`,`1 : 4`,`1 : 6`],`Volumes scale by the cube of the length factor: 2³ = 8.`],[8,3,`measurement`,`A runner covers 100 m in 12.5 s. What is the average speed in km/h?`,`28.8 km/h`,[`8 km/h`,`12.5 km/h`,`80 km/h`],`100 ÷ 12.5 = 8 m/s, and 8 × 3.6 = 28.8 km/h.`],[3,1,`algebra`,`What is the next number: 5, 10, 15, 20, …?`,`25`,[`21`,`30`,`24`],`The pattern counts up in fives.`],[3,2,`algebra`,`I think of a number and add 6. The answer is 10. What was my number?`,`4`,[`16`,`6`,`60`],`Undo adding 6 by taking 6 away: 10 − 6 = 4.`],[3,3,`algebra`,`Each shape stands for the same number in every place: ▲ + ▲ = 12. What is ▲?`,`6`,[`12`,`24`,`10`],`Two equal numbers make 12, so each is 12 ÷ 2 = 6.`],[4,1,`algebra`,`A pattern goes 1, 3, 9, 27, … What is the rule?`,`Multiply by 3`,[`Add 2`,`Add 3`,`Multiply by 2`],`Each number is three times the one before.`],[4,2,`algebra`,`A function machine doubles a number and then adds 1. Which number comes out when 7 goes in?`,`15`,[`16`,`9`,`14`],`Double 7 is 14, and 14 + 1 = 15.`],[4,3,`algebra`,`The same function machine (double, then add 1) gives out 21. Which number went in?`,`10`,[`11`,`20`,`42`],`Work backwards: 21 − 1 = 20, then halve it: 10.`],[5,1,`algebra`,`Simplify 2a + 3b + 4a.`,`6a + 3b`,[`9ab`,`6a + 3`,`9a`],`Collect like terms: 2a + 4a = 6a; 3b cannot be added to the a-terms.`],[5,2,`algebra`,`If a = 3 and b = 4, what is ab?`,`12`,[`7`,`34`,`1`],`ab means a × b = 3 × 4 = 12.`],[5,2,`algebra`,`What is the 10th term of the sequence that starts 4, 7, 10, 13, …?`,`31`,[`34`,`40`,`28`],`It goes up by 3: the nth term is 3n + 1, and 3 × 10 + 1 = 31.`],[5,3,`algebra`,`Which is an equation rather than an expression?`,`2x + 1 = 9`,[`2x + 1`,`x²`,`3(x − 4)`],`An equation has an equals sign joining two sides; an expression does not.`],[6,1,`algebra`,`If p = −2, what is 3p?`,`−6`,[`6`,`1`,`−5`],`3p means 3 × p, and 3 × (−2) = −6.`],[6,2,`algebra`,`Find x when 3(x − 2) = 12.`,`x = 6`,[`x = 4`,`x = 2`,`x = 14/3`],`Divide by 3: x − 2 = 4. Then add 2: x = 6.`],[6,2,`algebra`,`Which values of x make 2x + 1 < 9 true?`,`x < 4`,[`x > 4`,`x < 5`,`x = 4`],`Subtract 1: 2x < 8. Divide by 2: x < 4.`],[6,3,`algebra`,`Write an expression for the perimeter of a rectangle that is (x + 3) long and x wide.`,`4x + 6`,[`2x + 3`,`x² + 3x`,`4x + 3`],`Perimeter = 2 × length + 2 × width = 2(x + 3) + 2x = 4x + 6.`],[6,3,`algebra`,`a × a × a can be written as…`,`a³`,[`3a`,`a + 3`,`aaa³`],`Multiplying a by itself three times is a to the power 3.`],[7,1,`algebra`,`Where does the line y = 2x − 5 cross the y-axis?`,`At (0, −5)`,[`At (0, 2)`,`At (−5, 0)`,`At (0, 5)`],`In y = mx + c the line crosses the y-axis at c, here −5.`],[7,1,`algebra`,`Lines with the same gradient are parallel.`,`True`,[`False`],`The gradient measures steepness; equal steepness means the lines never meet.`],[7,2,`algebra`,`A line passes through (1, 2) and (3, 10). How steep is it (what is its gradient)?`,`4`,[`8`,`2`,`1/4`],`Gradient = change in y ÷ change in x = (10 − 2) ÷ (3 − 1) = 8 ÷ 2 = 4.`],[7,2,`algebra`,`What is the equation of the horizontal line through (0, 3)?`,`y = 3`,[`x = 3`,`y = 3x`,`y = x + 3`],`Every point on a horizontal line has the same y-value, here 3.`],[7,3,`algebra`,`A sequence goes 1, 4, 9, 16, … What is its nth term?`,`n²`,[`3n − 2`,`n + 3`,`2n`],`These are the square numbers: 1², 2², 3², 4².`],[7,3,`algebra`,`A sequence goes 2, 6, 18, 54, … What kind of sequence is it?`,`Geometric`,[`Arithmetic`,`Square numbers`,`Fibonacci`],`Each term is multiplied by the same number (3), which makes it geometric.`],[8,1,`algebra`,`Solve x² − 5x + 6 = 0.`,`x = 2 or x = 3`,[`x = −2 or x = −3`,`x = 1 or x = 6`,`x = 5 or x = 6`],`It factorises to (x − 2)(x − 3) = 0, so x = 2 or x = 3.`],[8,1,`algebra`,`Which graph has the shape of a U (a parabola)?`,`y = x²`,[`y = 2x`,`y = 1/x`,`y = 3`],`y = x² makes a symmetrical U-shaped curve called a parabola; y = 2x is a straight line.`],[8,2,`algebra`,`In the sequence 3, 5, 9, 15, 23, … the differences are 2, 4, 6, 8. What kind of sequence is it?`,`Quadratic`,[`Arithmetic`,`Geometric`,`Linear`],`When the second differences are constant (here 2), the nth term contains n².`],[8,2,`algebra`,`If f(x) = 2x² − 1, what is f(3)?`,`17`,[`35`,`11`,`12`],`f(3) = 2 × 3² − 1 = 2 × 9 − 1 = 17.`],[8,3,`algebra`,`What is the turning point of the curve y = (x − 2)² + 5?`,`(2, 5)`,[`(−2, 5)`,`(5, 2)`,`(2, −5)`],`The squared bracket is smallest (zero) when x = 2, and then y = 5.`],[8,3,`algebra`,`x² + 6x + 9 is a perfect square. Which one?`,`(x + 3)²`,[`(x + 9)²`,`(x + 6)²`,`(x − 3)²`],`(x + 3)² = x² + 3x + 3x + 9 = x² + 6x + 9.`],[3,1,`data`,`Which of these is impossible?`,`A cat laying an egg`,[`Rain on a cloudy day`,`Getting tails on a coin`,`Seeing a bird today`],`Cats are mammals and give birth to live kittens; they never lay eggs.`],[3,2,`data`,`In a block graph, each block is one child. How many children chose football if there are 7 blocks?`,`7`,[`1`,`14`,`70`],`One block for each child, so 7 blocks show 7 children.`],[3,3,`data`,`A spinner is half red and half blue. Red and blue are equally likely.`,`True`,[`False`],`Equal-sized parts give equal chances: each colour has a chance of 1 in 2.`],[4,1,`data`,`In a bar chart, what does the tallest bar show?`,`The biggest amount`,[`The smallest amount`,`The newest result`,`The middle value`],`The height of each bar shows how many or how much, so the tallest bar is the biggest amount.`],[4,2,`data`,`A tally has two complete bundles of five and then three single lines. How many does it show?`,`13`,[`8`,`23`,`5`],`Each bundle is 5, so 5 + 5 + 3 = 13.`],[4,3,`data`,`A bag holds 2 red, 3 green and 5 yellow sweets. Which colour is least likely to be picked?`,`Red`,[`Green`,`Yellow`,`They are all equally likely`],`Red has the fewest sweets (2 out of 10), so it is least likely.`],[5,1,`data`,`What is the probability of picking a vowel from the letters of the word MATHS?`,`1/5`,[`2/5`,`1/2`,`4/5`],`MATHS has 5 letters and only one vowel, A.`],[5,2,`data`,`Height measured in centimetres is discrete data.`,`False`,[`True`],`Height can take any value in a range (such as 152.3 cm), so it is continuous data.`],[5,2,`data`,`In a pie chart of 36 pupils, how many degrees stand for each pupil?`,`10°`,[`36°`,`1°`,`5°`],`The whole circle is 360°, and 360° ÷ 36 = 10° per pupil.`],[5,3,`data`,`Two ordinary dice are rolled. How many different outcomes are possible?`,`36`,[`12`,`11`,`6`],`Each of the 6 results on the first die can pair with 6 on the second: 6 × 6 = 36.`],[6,1,`data`,`A coin landed on heads 27 times in 50 tosses. What is the relative frequency of heads?`,`0.54`,[`0.27`,`0.5`,`27`],`Relative frequency = 27 ÷ 50 = 0.54.`],[6,2,`data`,`Events that cannot happen at the same time are called…`,`mutually exclusive`,[`independent`,`equally likely`,`certain`],`Rolling a 2 and rolling a 5 with one throw cannot both happen: they are mutually exclusive.`],[6,2,`data`,`Which of these is qualitative (not numerical) data?`,`Favourite colour`,[`Height`,`Shoe size`,`Number of pets`],`Qualitative data are words or categories; the others are counts or measurements.`],[6,3,`data`,`A frequency table shows 3 children with 0 pets, 4 with 1 pet and 3 with 2 pets. What is the mean number of pets?`,`1`,[`1.5`,`3`,`0.5`],`Total pets = 0 + 4 + 6 = 10 among 10 children, so the mean is 1.`],[7,1,`data`,`Which pair of quantities is likely to show negative correlation?`,`A car's age and its value`,[`Height and shoe size`,`Hours of study and test marks`,`Temperature and ice-cream sales`],`As a car gets older its value usually falls: one goes up while the other goes down.`],[7,2,`data`,`A survey of everyone in a population, rather than a sample, is called a…`,`census`,[`poll`,`tally`,`trial`],`A census collects data from every member of the population.`],[7,2,`data`,`In a stem-and-leaf diagram, the stem 4 with a leaf of 7 stands for…`,`47`,[`4.7`,`74`,`11`],`The stem holds the tens and the leaf the ones: 4 | 7 means 47.`],[7,3,`data`,`P(A) = 0.3 and P(B) = 0.5 for two mutually exclusive events. What is P(A or B)?`,`0.8`,[`0.15`,`0.2`,`0.35`],`For mutually exclusive events, add the probabilities: 0.3 + 0.5 = 0.8.`],[8,1,`data`,`On a histogram with unequal class widths, what does the height of each bar show?`,`Frequency density`,[`Frequency`,`Class width`,`Cumulative frequency`],`Frequency density = frequency ÷ class width, so the area of each bar shows the frequency.`],[8,2,`data`,`A bag has 3 red and 2 blue counters. One is taken and not replaced, then another is taken. What is the probability both are red?`,`3/10`,[`9/25`,`6/25`,`1/2`],`3/5 × 2/4 = 6/20 = 3/10. The second fraction changes because the first counter was not put back.`],[8,2,`data`,`On a cumulative frequency graph of 80 values, where do you read off the median?`,`At the 40th value`,[`At the 80th value`,`At the 20th value`,`At the highest point`],`The median is the middle value: half of 80 is 40.`],[8,3,`data`,`Of 30 students, 18 study French, 12 study Spanish and 5 study both. How many study neither?`,`5`,[`0`,`10`,`7`],`French or Spanish = 18 + 12 − 5 = 25, so 30 − 25 = 5 study neither.`],[8,3,`data`,`A sample of 50 fish from a lake is tagged and released. Later, 4 of 40 fish caught are tagged. Estimate the number of fish in the lake.`,`500`,[`200`,`90`,`2,000`],`4/40 = 1/10 of the fish are tagged, so 50 tagged fish suggest about 50 × 10 = 500 in all.`]],[[3,1,`number`,`Which number is made of 4 tens and 7 ones?`,`47`,[`74`,`11`,`407`],`4 tens are 40, and 40 + 7 = 47.`],[3,2,`number`,`Which of these numbers is the biggest: 309, 390, 339 or 93?`,`390`,[`309`,`339`,`93`],`All but 93 have 3 hundreds; then compare tens: 390 has 9 tens, the most.`],[3,3,`number`,`How many 5-taka coins make 50 taka?`,`10`,[`5`,`45`,`250`],`50 ÷ 5 = 10 coins.`],[4,1,`number`,`Which number is 1,000 less than 7,250?`,`6,250`,[`7,150`,`6,150`,`7,240`],`Only the thousands digit changes: 7 thousands becomes 6 thousands.`],[4,2,`number`,`Which list shows all the factor pairs of 12?`,`1 × 12, 2 × 6, 3 × 4`,[`2 × 6, 3 × 4`,`1 × 12, 2 × 6`,`1 × 12, 3 × 4, 4 × 3, 6 × 2`],`1, 2, 3, 4, 6 and 12 divide 12 exactly, making three different pairs.`],[4,3,`number`,`Which of these numbers rounds to 500 when rounded to the nearest hundred?`,`462`,[`438`,`551`,`449`],`462 is nearer to 500 than to 400; 438 and 449 round down to 400, and 551 rounds up to 600.`],[5,1,`number`,`Which is the first prime number after 7?`,`11`,[`9`,`8`,`13`],`8, 9 and 10 all have other factors; 11 has only 1 and itself.`],[5,2,`number`,`Use 15 × 100 − 15 to work out 15 × 99.`,`1,485`,[`1,500`,`1,515`,`1,395`],`15 × 99 is one lot of 15 less than 15 × 100: 1,500 − 15 = 1,485.`],[5,3,`number`,`A positive number multiplied by itself gives 144. What is the number?`,`12`,[`14`,`72`,`11`],`12 × 12 = 144, so 12 is the square root of 144.`],[6,1,`number`,`Which quick calculation checks that 23 × 19 = 437 is about right?`,`20 × 20 = 400`,[`23 + 19 = 42`,`25 × 25 = 625`,`437 ÷ 2 = 218.5`],`Rounding both numbers to 20 gives 400, close to 437, so the answer is sensible.`],[6,2,`number`,`In a desert the temperature falls from 35 °C by day to −5 °C at night. By how many degrees does it fall?`,`40`,[`30`,`−40`,`35`],`From 35 down to 0 is 35 degrees, and 5 more to −5 makes 40.`],[6,3,`number`,`What is the product of the first four prime numbers?`,`210`,[`105`,`24`,`17`],`2 × 3 × 5 × 7 = 210. (Their sum is 17.)`],[7,1,`number`,`How many tenths are there in 0.5?`,`5`,[`50`,`0.05`,`10`],`0.5 is five tenths, so 0.5 ÷ 0.1 = 5.`],[7,2,`number`,`Which is larger: 3⁴ or 4³?`,`3⁴`,[`4³`,`They are equal`,`It cannot be told`],`3⁴ = 81 and 4³ = 64.`],[7,3,`number`,`How many significant figures does 0.00720 have?`,`3`,[`2`,`5`,`6`],`Leading zeros do not count; 7, 2 and the final 0 (which shows accuracy) do.`],[8,1,`number`,`Write one thousandth as a power of 10.`,`10⁻³`,[`10³`,`−10³`,`10⁻²`],`1/1000 = 1/10³ = 10⁻³.`],[8,2,`number`,`Rationalise the denominator of 1/√2.`,`√2/2`,[`2/√2`,`1/2`,`√2`],`Multiply top and bottom by √2: √2/(√2 × √2) = √2/2.`],[8,2,`number`,`Without a calculator: is √99 more or less than 10?`,`A little less than 10`,[`A little more than 10`,`Exactly 10`,`About 50`],`10 × 10 = 100, and 99 is just under 100, so √99 is a little less than 10 (about 9.95).`],[3,2,`fractions`,`What fraction of a week is one day?`,`1/7`,[`1/5`,`1/10`,`1/30`],`A week has 7 days, so one day is one seventh of it.`],[4,1,`fractions`,`How many quarters are there in 2 wholes?`,`8`,[`4`,`2`,`6`],`Each whole has 4 quarters: 2 × 4 = 8.`],[4,3,`fractions`,`Which fraction lies between 1/4 and 3/4?`,`1/2`,[`1/5`,`7/8`,`1/10`],`1/4 = 0.25 and 3/4 = 0.75; 1/2 = 0.5 is between them.`],[6,3,`fractions`,`Red and green sweets in a bag are in the ratio 3 : 2. What fraction of the sweets are green?`,`2/5`,[`2/3`,`3/5`,`1/2`],`There are 3 + 2 = 5 parts, and 2 of them are green.`],[7,1,`fractions`,`On a 1,000-taka item, which is the bigger saving: 20 % off or 150 taka off?`,`20 % off`,[`150 taka off`,`They are the same`,`It depends on the shop`],`20 % of 1,000 taka is 200 taka, which is more than 150 taka.`],[8,1,`fractions`,`Which is larger: two-thirds of 60 or three-quarters of 52?`,`Two-thirds of 60`,[`Three-quarters of 52`,`They are equal`,`It cannot be worked out`],`Two-thirds of 60 is 40; three-quarters of 52 is 39.`],[3,2,`geometry`,`How many sides do two triangles have altogether?`,`6`,[`3`,`5`,`9`],`Each triangle has 3 sides: 3 + 3 = 6.`],[3,3,`geometry`,`Which shape has four equal sides, but corners that are not right angles?`,`A rhombus`,[`A square`,`A rectangle`,`A circle`],`A rhombus is like a square pushed over, so its angles are not 90°.`],[4,2,`geometry`,`Which 3D shape has six rectangular faces that are not all squares?`,`A cuboid`,[`A cube`,`A pyramid`,`A cylinder`],`A cuboid, like a shoebox, has rectangular faces; a cube's six faces are all squares.`],[4,3,`geometry`,`At exactly 3 o'clock, what kind of angle do the hands of a clock make?`,`A right angle`,[`An acute angle`,`A straight angle`,`A reflex angle`],`The hands point at 12 and 3: a quarter turn, which is 90°.`],[5,3,`geometry`,`How many diagonals does a pentagon have?`,`5`,[`4`,`10`,`3`],`Each of the 5 corners joins to 2 non-neighbouring corners: 5 × 2 ÷ 2 = 5.`],[6,1,`geometry`,`What is the name of a polygon with 10 sides?`,`A decagon`,[`A nonagon`,`A dodecagon`,`An octagon`],`Deca means ten, as in decade (ten years).`],[6,2,`geometry`,`Two angles that add up to 90° are called…`,`complementary`,[`supplementary`,`vertically opposite`,`reflex`],`For example, 30° and 60° are complementary.`],[6,3,`geometry`,`Which word describes a pair of angles whose sum is a straight angle (180°)?`,`Supplementary`,[`Complementary`,`Acute`,`Alternate`],`Angles on a straight line are supplementary, such as 110° and 70°.`],[7,3,`geometry`,`The angles of a triangle are in the ratio 1 : 2 : 3. What is the largest angle?`,`90°`,[`60°`,`120°`,`30°`],`There are 6 parts and 180° ÷ 6 = 30°, so the angles are 30°, 60° and 90°.`],[8,1,`geometry`,`A right-angled triangle has a hypotenuse of 10 cm and an angle of 60°. How long is the side next to the 60° angle?`,`5 cm`,[`8.7 cm`,`10 cm`,`6 cm`],`Adjacent = hypotenuse × cos 60° = 10 × 0.5 = 5 cm.`],[8,2,`geometry`,`Which equation describes a circle centred at the origin with radius 5?`,`x² + y² = 25`,[`x + y = 5`,`x² + y² = 5`,`y = x² + 5`],`Every point (x, y) on the circle is 5 from the origin, so by Pythagoras x² + y² = 5² = 25.`],[8,3,`geometry`,`Add the vectors (2, 3) and (4, −1).`,`(6, 2)`,[`(8, −3)`,`(6, 4)`,`(−2, 4)`],`Add the parts separately: 2 + 4 = 6 and 3 + (−1) = 2.`],[3,1,`measurement`,`Which is the longest: 1 m, 90 cm or 150 cm?`,`150 cm`,[`1 m`,`90 cm`,`They are all the same`],`1 m is 100 cm, so 150 cm is the longest.`],[3,2,`measurement`,`About how many weeks are there in a year?`,`52`,[`12`,`100`,`365`],`365 days ÷ 7 days is a little more than 52 weeks.`],[4,1,`measurement`,`What time is it 45 minutes after 2:30?`,`3:15`,[`3:45`,`2:75`,`3:00`],`30 minutes takes you to 3:00, and 15 more makes 3:15.`],[4,2,`measurement`,`A recipe needs 750 g of flour. How many kilograms is that?`,`0.75 kg`,[`7.5 kg`,`75 kg`,`0.075 kg`],`1 kg = 1,000 g, so 750 g = 0.75 kg.`],[5,1,`measurement`,`A square has a perimeter of 20 cm. What is its area?`,`25 cm²`,[`20 cm²`,`16 cm²`,`100 cm²`],`Each side is 20 ÷ 4 = 5 cm, so the area is 5 × 5 = 25 cm².`],[6,1,`measurement`,`Which unit is most sensible for the distance between two cities?`,`Kilometres`,[`Millimetres`,`Centimetres`,`Grams`],`Cities are many kilometres apart; grams measure mass, not length.`],[6,2,`measurement`,`A tank measures 50 cm by 40 cm by 30 cm. How many litres of water does it hold when full?`,`60 litres`,[`600 litres`,`6 litres`,`120 litres`],`50 × 40 × 30 = 60,000 cm³, and 1,000 cm³ = 1 litre.`],[6,3,`measurement`,`A journey takes 2.5 hours. How long is that in hours and minutes?`,`2 hours 30 minutes`,[`2 hours 50 minutes`,`2 hours 5 minutes`,`2 hours 25 minutes`],`0.5 of an hour is half of 60 minutes, which is 30 minutes.`],[7,2,`measurement`,`A car uses 8 litres of petrol for every 100 km. How much does it use on a 250 km trip?`,`20 litres`,[`16 litres`,`25 litres`,`32 litres`],`250 km is 2.5 lots of 100 km: 2.5 × 8 = 20 litres.`],[7,3,`measurement`,`How many cubic centimetres are there in 5 litres?`,`5,000`,[`500`,`50`,`50,000`],`1 litre is 1,000 cm³, so 5 litres is 5,000 cm³.`],[8,1,`measurement`,`What is the curved surface area of a cylinder with radius 3 cm and height 10 cm? (Use π ≈ 3.14.)`,`188.4 cm²`,[`94.2 cm²`,`282.6 cm²`,`30 cm²`],`Curved area = 2πrh = 2 × 3.14 × 3 × 10 = 188.4 cm².`],[8,2,`measurement`,`What is the volume of a sphere with radius 3 cm? (Use π ≈ 3.14.)`,`113.04 cm³`,[`28.26 cm³`,`37.68 cm³`,`339.12 cm³`],`V = 4/3 × π × r³ = 4/3 × 3.14 × 27 = 113.04 cm³.`],[5,1,`algebra`,`If y = 2x and x = 6, what is y?`,`12`,[`8`,`26`,`3`],`y is twice x: 2 × 6 = 12.`],[5,3,`algebra`,`Which expression means ‘five more than n’?`,`n + 5`,[`5n`,`n − 5`,`5 − n`],`‘More than’ means add: n + 5. 5n means 5 times n.`],[6,1,`algebra`,`Take 2x away from 5x.`,`3x`,[`3`,`7x`,`10x`],`Five x's take away two x's leaves three x's.`],[6,2,`algebra`,`Write ‘four less than the square of n’ in algebra.`,`n² − 4`,[`4 − n²`,`(n − 4)²`,`2n − 4`],`Square n first (n²), then take away 4.`],[6,3,`algebra`,`Solve 5 − x = 2.`,`x = 3`,[`x = 7`,`x = −3`,`x = 2.5`],`5 − 3 = 2, so x = 3.`],[7,3,`algebra`,`A straight line has gradient 2 and passes through (0, 1). What is its equation?`,`y = 2x + 1`,[`y = x + 2`,`y = 2x`,`y = x + 1`],`In y = mx + c, the gradient m is 2 and c, where it meets the y-axis, is 1.`],[8,1,`algebra`,`Factorise x² + 7x + 12.`,`(x + 3)(x + 4)`,[`(x + 2)(x + 6)`,`(x + 1)(x + 12)`,`(x + 7)(x + 12)`],`3 × 4 = 12 and 3 + 4 = 7.`],[8,2,`algebra`,`Solve x² = 2x.`,`x = 0 or x = 2`,[`x = 2 only`,`x = 0 only`,`x = √2`],`x² − 2x = 0 gives x(x − 2) = 0. Dividing both sides by x would lose the solution x = 0.`],[8,3,`algebra`,`Which inequality describes every number greater than −1 and no more than 3?`,`−1 < x ≤ 3`,[`−1 ≤ x < 3`,`x > 3`,`−1 > x ≥ 3`],`‘Greater than −1’ uses <, and ‘no more than 3’ includes 3, so ≤.`],[4,1,`data`,`In a class vote, 5 children choose red, 8 choose blue and 3 choose green. Which colour is the mode?`,`Blue`,[`Red`,`Green`,`They are all equal`],`The mode is the most popular choice: blue, with 8 votes.`],[5,1,`data`,`Three children have 4, 6 and 8 stickers. If they share them out equally, how many does each get?`,`6`,[`4`,`8`,`18`],`4 + 6 + 8 = 18 stickers, and 18 ÷ 3 = 6. This fair share is the mean.`],[5,3,`data`,`An event with a probability of 1/2 is described as…`,`an even chance`,[`impossible`,`certain`,`unlikely`],`An even chance is 1/2, halfway between impossible (0) and certain (1).`],[6,2,`data`,`For the scores 3, 7, 7, 9 and 14, which averages are equal to 7?`,`Both the mode and the median`,[`Only the mean`,`Only the mode`,`All three averages`],`7 appears most and is in the middle; the mean is 40 ÷ 5 = 8.`],[7,2,`data`,`What is the range of the temperatures −3 °C, 5 °C and 2 °C?`,`8 °C`,[`2 °C`,`4 °C`,`7 °C`],`Range = highest − lowest = 5 − (−3) = 8 °C.`],[8,1,`data`,`In a box plot, what does the box itself show?`,`The middle 50 % of the data`,[`Every single value`,`Only the mean`,`The highest 25 % of the data`],`The box runs from the lower quartile to the upper quartile, with a line at the median.`],[8,2,`data`,`What is the lower quartile of 1, 3, 5, 7, 9, 11, 13?`,`3`,[`1`,`5`,`7`],`The median is 7; the lower half is 1, 3, 5, whose middle value is 3.`],[8,3,`data`,`A biased coin lands heads with probability 0.6. What is the probability of two heads in a row?`,`0.36`,[`1.2`,`0.6`,`0.16`],`The tosses are independent, so multiply: 0.6 × 0.6 = 0.36.`]]].flatMap(t=>e(`math`,t));export{t as QUESTIONS};